            out_BUS_AWLOCK         : out UNSIGNED(1 downto 0);
            out_BUS_AWCACHE        : out UNSIGNED(3 downto 0);
            out_BUS_AWPROT         : out UNSIGNED(2 downto 0);
            out_BUS_AWQOS          : out UNSIGNED(3 downto 0);
            out_BUS_AWREGION       : out UNSIGNED(3 downto 0);
            out_BUS_AWUSER         : out UNSIGNED(C_M_AXI_AWUSER_WIDTH-1 downto 0);
            out_BUS_AWVALID        : out STD_LOGIC;
            in_BUS_AWREADY         : in  STD_LOGIC;
            out_BUS_WID            : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            out_BUS_WDATA          : out UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
            out_BUS_WSTRB          : out UNSIGNED(BUS_DATA_WIDTH/8-1 downto 0);
            out_BUS_WLAST          : out STD_LOGIC;
            out_BUS_WUSER          : out UNSIGNED(C_M_AXI_WUSER_WIDTH-1 downto 0);
            out_BUS_WVALID         : out STD_LOGIC;
            in_BUS_WREADY          : in  STD_LOGIC;
            in_BUS_BID             : in  UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            in_BUS_BRESP           : in  UNSIGNED(1 downto 0);
            in_BUS_BUSER           : in  UNSIGNED(C_M_AXI_BUSER_WIDTH-1 downto 0);
            in_BUS_BVALID          : in  STD_LOGIC;
            out_BUS_BREADY         : out STD_LOGIC;
            in_AXI_AWID            : in  UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            in_AXI_AWADDR          : in  UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);
            in_AXI_AWLEN           : in  UNSIGNED(31 downto 0);
            in_AXI_AWVALID         : in  STD_LOGIC;
            out_AXI_AWREADY        : out UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
            in_AXI_BURST_REQ       : in  UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
            out_AXI_BURST_ID       : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            out_AXI_BURST_LEN      : out UNSIGNED(7 downto 0);
            out_AXI_BURST_ACK      : out STD_LOGIC;
            out_AXI_WID            : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            in_AXI_WDATA           : in  UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
            in_AXI_WSTRB           : in  UNSIGNED(BUS_DATA_WIDTH/8-1 downto 0);
            in_AXI_WVALID          : in  STD_LOGIC;
            out_AXI_WREADY         : out STD_LOGIC;
            out_AXI_BID            : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
            out_AXI_BVALID         : out STD_LOGIC;
            in_AXI_BREADY          : in  UNSIGNED(NUM_WRITE_PORTS-1 downto 0));
    end component vertex_map_gmem_m_axi_write;
    
    component vertex_map_gmem_m_axi_arbiter is
        generic(
            STRATEGY      : STRING := "load_balance";
            PORTS_WIDTH   : INTEGER := 2;
            PORTS         : INTEGER := 4);
        port (
            clk           : in  STD_LOGIC;
            reset         : in  STD_LOGIC;
            s_ready       : in  UNSIGNED;
            s_valid       : out STD_LOGIC;
            s_index       : out UNSIGNED;
            m_valid       : in  UNSIGNED;
            m_ready       : out UNSIGNED);
    end component vertex_map_gmem_m_axi_arbiter; 
    

    

    

    --========================Constant========================
    constant NUM_READ_PORTS  : INTEGER := 4;
    constant NUM_WRITE_PORTS : INTEGER := 1;
    --========================Local Signals===================
    -- AW/W/B channel signals 
    signal AWID_FromArbiterToBus    : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal AWADDR_FromArbiterToBus  : UNSIGNED(C_M_AXI_ADDR_WIDTH-1 downto 0);
    signal AWLEN_FromArbiterToBus   : UNSIGNED(31 downto 0);
    signal AWVALID_FromArbiterToBus : STD_LOGIC;
    signal AWREADY_FromBusToArbiter : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    signal BURST_ID_FromBusToChan   : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal BURST_LEN_FromBusToChan  : UNSIGNED(7 downto 0);
    signal BURST_REQ_FromChanToBus  : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    signal BURST_ACK_FromBusToChan  : STD_LOGIC;
    signal WID_FromBusToArbiter     : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal WDATA_FromArbiterToBus   : UNSIGNED(C_M_AXI_DATA_WIDTH-1 downto 0);
    signal WSTRB_FromArbiterToBus   : UNSIGNED(C_M_AXI_DATA_WIDTH/8-1 downto 0);
    signal WVALID_FromArbiterToBus  : STD_LOGIC;
    signal WREADY_FromBusToArbiter  : STD_LOGIC;
    signal BID_FromBusToChan        : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal BVALID_FromBusToChan     : STD_LOGIC;
    signal BREADY_FromChanToBus     : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);

    type AWID_ARRAY   is array (0 to NUM_WRITE_PORTS-1) of UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    type AWADDR_ARRAY is array (0 to NUM_WRITE_PORTS-1) of UNSIGNED(C_M_AXI_ADDR_WIDTH-1 downto 0);
    type AWLEN_ARRAY  is array (0 to NUM_WRITE_PORTS-1) of UNSIGNED(31 downto 0);
    type WDATA_ARRAY  is array (0 to NUM_WRITE_PORTS-1) of UNSIGNED(C_M_AXI_DATA_WIDTH-1 downto 0);
    type WSTRB_ARRAY  is array (0 to NUM_WRITE_PORTS-1) of UNSIGNED(C_M_AXI_DATA_WIDTH/8-1 downto 0);
    signal awid_index        : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal AXI_AWID_FromChanToArbiter    : AWID_ARRAY;
    signal AXI_AWADDR_FromChanToArbiter  : AWADDR_ARRAY;
    signal AXI_AWLEN_FromChanToArbiter   : AWLEN_ARRAY;
    signal AXI_AWVALID_FromChanToArbiter : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    signal AXI_AWREADY_FromArbiterToChan : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    signal AXI_WID_FromChanToNone        : AWID_ARRAY;
    signal AXI_WDATA_FromChanToArbiter   : WDATA_ARRAY;
    signal AXI_WSTRB_FromChanToArbiter   : WSTRB_ARRAY;
    signal AXI_WVALID_FromChanToArbiter  : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    signal AXI_WREADY_FromArbiterToChan  : UNSIGNED(NUM_WRITE_PORTS-1 downto 0);
    -- AR/R channel signals 
    signal ARID_FromArbiterToBus      : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal ARADDR_FromArbiter         : UNSIGNED(C_M_AXI_ADDR_WIDTH-1 downto 0);
    signal ARLEN_FromArbiter          : UNSIGNED(31 downto 0);
    signal ARVALID_FromArbiter        : STD_LOGIC;
    signal ARREADY_ToArbiter          : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    signal ARADDR_ToBus               : UNSIGNED(C_M_AXI_ADDR_WIDTH-1 downto 0);
    signal ARLEN_ToBus                : UNSIGNED(31 downto 0);
    signal ARVALID_ToBus              : STD_LOGIC;
    signal ARREADY_FromBus            : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    
    signal RID_FromBusToChan          : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal RDATA_FromBus              : UNSIGNED(C_M_AXI_DATA_WIDTH-1 downto 0);
    signal RLAST_FromBus              : UNSIGNED(1 downto 0);
    signal RVALID_FromBus             : STD_LOGIC;
    signal RREADY_ToBus               : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    signal RBURST_READY_ToBus         : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    signal RDATA_ToChan               : UNSIGNED(C_M_AXI_DATA_WIDTH-1 downto 0);
    signal RLAST_ToChan               : UNSIGNED(1 downto 0);
    signal RVALID_ToChan              : STD_LOGIC;
    signal RREADY_FromChan            : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    signal RBURST_READY_FromChan      : UNSIGNED(NUM_READ_PORTS-1 downto 0);

    type ARID_ARRAY   is array (0 to NUM_READ_PORTS-1) of UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    type ARADDR_ARRAY is array (0 to NUM_READ_PORTS-1) of UNSIGNED(C_M_AXI_ADDR_WIDTH-1 downto 0);
    type ARLEN_ARRAY  is array (0 to NUM_READ_PORTS-1) of UNSIGNED(31 downto 0);
    signal arid_index                    : UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
    signal AXI_ARID_FromChanToArbiter    : ARID_ARRAY;
    signal AXI_ARADDR_FromChanToArbiter  : ARADDR_ARRAY;
    signal AXI_ARLEN_FromChanToArbiter   : ARLEN_ARRAY;
    signal AXI_ARVALID_FromChanToArbiter : UNSIGNED(NUM_READ_PORTS-1 downto 0);
    signal AXI_ARREADY_FromArbiterToChan : UNSIGNED(NUM_READ_PORTS-1 downto 0);

    
begin
    -- AXI Ports Initialization 
    -- Kernel Ports Initialization 
    I_CH0_AWREADY   <= '0';
    I_CH0_WREADY    <= '0';
    I_CH0_BVALID    <= '0';
    I_CH1_AWREADY   <= '0';
    I_CH1_WREADY    <= '0';
    I_CH1_BVALID    <= '0';
    I_CH2_AWREADY   <= '0';
    I_CH2_WREADY    <= '0';
    I_CH2_BVALID    <= '0';
    -- Internal Ports Mapping 
    ARID_FromArbiterToBus         <= AXI_ARID_FromChanToArbiter(TO_INTEGER(arid_index)); 
    ARADDR_FromArbiter            <= AXI_ARADDR_FromChanToArbiter(TO_INTEGER(arid_index));
    ARLEN_FromArbiter             <= AXI_ARLEN_FromChanToArbiter(TO_INTEGER(arid_index));
    AWID_FromArbiterToBus         <= AXI_AWID_FromChanToArbiter(TO_INTEGER(awid_index));
    AWADDR_FromArbiterToBus       <= AXI_AWADDR_FromChanToArbiter(TO_INTEGER(awid_index));
    AWLEN_FromArbiterToBus        <= AXI_AWLEN_FromChanToArbiter(TO_INTEGER(awid_index));
    WDATA_FromArbiterToBus        <= AXI_WDATA_FromChanToArbiter(TO_INTEGER(WID_FromBusToArbiter));
    WSTRB_FromArbiterToBus        <= AXI_WSTRB_FromChanToArbiter(TO_INTEGER(WID_FromBusToArbiter));
    -- flush logic 
    --========================Instantiation========================
    -- ++++++++++++++++++++++ STORE UNITS ++++++++++++++++++++++ 
    -- store_unit for channel 5
    store_unit_5 : vertex_map_gmem_m_axi_store
    generic map (
        C_TARGET_ADDR          => C_TARGET_ADDR,
        C_M_AXI_ID_WIDTH       => C_M_AXI_ID_WIDTH,
        C_ID_VALUE             => 0,
        NUM_WRITE_OUTSTANDING  => CH5_NUM_WRITE_OUTSTANDING,
        MAX_WRITE_BURST_LENGTH => MAX_WRITE_BURST_LENGTH,
        BUS_ADDR_WIDTH         => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH         => C_M_AXI_DATA_WIDTH,
        USER_DW                => CH5_USER_DW,
        USER_AW                => CH5_USER_AW,
        USER_MAXREQS           => USER_MAXREQS,
        BUFFER_IMPL            => MAXI_BUFFER_IMPL) 
    port map (
        ACLK                   => ACLK,
        ARESET                 => ARESET,
        ACLK_EN                => ACLK_EN,
        out_AXI_AWID           => AXI_AWID_FromChanToArbiter(0),
        out_AXI_AWADDR         => AXI_AWADDR_FromChanToArbiter(0),
        out_AXI_AWLEN          => AXI_AWLEN_FromChanToArbiter(0),
        out_AXI_AWVALID        => AXI_AWVALID_FromChanToArbiter(0),
        in_AXI_AWREADY         => AXI_AWREADY_FromArbiterToChan(0),
        in_AXI_BURST_ID        => BURST_ID_FromBusToChan,
        in_AXI_BURST_LEN       => BURST_LEN_FromBusToChan,
        in_AXI_BURST_ACK       => BURST_ACK_FromBusToChan,
        out_AXI_BURST_REQ      => BURST_REQ_FromChanToBus(0),
        out_AXI_WID            => AXI_WID_FromChanToNone(0),
        out_AXI_WDATA          => AXI_WDATA_FromChanToArbiter(0),
        out_AXI_WSTRB          => AXI_WSTRB_FromChanToArbiter(0),
        out_AXI_WVALID         => AXI_WVALID_FromChanToArbiter(0),
        in_AXI_WREADY          => AXI_WREADY_FromArbiterToChan(0),
        in_AXI_BID             => BID_FromBusToChan,
        in_AXI_BVALID          => BVALID_FromBusToChan,
        out_AXI_BREADY         => BREADY_FromChanToBus(0),
        in_HLS_AWADDR          => UNSIGNED(I_CH5_AWADDR),
        in_HLS_AWLEN           => UNSIGNED(I_CH5_AWLEN) ,
        in_HLS_AWVALID         => I_CH5_AWVALID         ,
        out_HLS_AWREADY        => I_CH5_AWREADY         ,
        in_HLS_WDATA           => UNSIGNED(I_CH5_WDATA) ,
        in_HLS_WSTRB           => UNSIGNED(I_CH5_WSTRB) ,
        in_HLS_WVALID          => I_CH5_WVALID          ,
        out_HLS_WREADY         => I_CH5_WREADY          ,
        out_HLS_BVALID         => I_CH5_BVALID          ,
        in_HLS_BREADY          => I_CH5_BREADY          ); 
       awid_index <= TO_UNSIGNED(0, awid_index'length);
       AXI_AWREADY_FromArbiterToChan <= AWREADY_FromBusToArbiter;
       AWVALID_FromArbiterToBus <= AXI_AWVALID_FromChanToArbiter(0);
       AXI_WREADY_FromArbiterToChan(0) <= WREADY_FromBusToArbiter;
       WVALID_FromArbiterToBus <= AXI_WVALID_FromChanToArbiter(0);
       
        
    -- ++++++++++++++++++++++ LOAD UNITS ++++++++++++++++++++++  
    -- load_unit for channel 0
    load_unit_0 : vertex_map_gmem_m_axi_load
    generic map(
        C_TARGET_ADDR          => C_TARGET_ADDR,
        C_M_AXI_ID_WIDTH       => C_M_AXI_ID_WIDTH,
        C_ID_VALUE             => 1,
        NUM_READ_OUTSTANDING   => CH0_NUM_READ_OUTSTANDING,
        MAX_READ_BURST_LENGTH  => MAX_READ_BURST_LENGTH,
        BUS_ADDR_WIDTH         => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH         => C_M_AXI_DATA_WIDTH,
        USER_DW                => CH0_USER_DW,
        USER_AW                => CH0_USER_AW,
        USER_MAXREQS           => USER_MAXREQS,
        USER_RFIFONUM_WIDTH    => CH0_USER_RFIFONUM_WIDTH,
        BUFFER_IMPL            => MAXI_BUFFER_IMPL)
    port map(
        ACLK                   => ACLK,
        ARESET                 => ARESET,
        ACLK_EN                => ACLK_EN,
        out_AXI_ARID           => AXI_ARID_FromChanToArbiter(1),
        out_AXI_ARADDR         => AXI_ARADDR_FromChanToArbiter(1),
        out_AXI_ARLEN          => AXI_ARLEN_FromChanToArbiter(1),
        out_AXI_ARVALID        => AXI_ARVALID_FromChanToArbiter(1),
        in_AXI_ARREADY         => AXI_ARREADY_FromArbiterToChan(1),
        in_AXI_RID             => RID_FromBusToChan,
        in_AXI_RDATA           => RDATA_ToChan,
        in_AXI_RLAST           => RLAST_ToChan,
        in_AXI_RVALID          => RVALID_ToChan,
        out_AXI_RREADY         => RREADY_FromChan(1),
        out_AXI_RBURST_READY   => RBURST_READY_FromChan(1),
        in_HLS_ARADDR          => UNSIGNED(I_CH0_ARADDR),
        in_HLS_ARLEN           => UNSIGNED(I_CH0_ARLEN),
        in_HLS_ARVALID         => I_CH0_ARVALID,
        out_HLS_ARREADY        => I_CH0_ARREADY,
        out_HLS_RVALID         => I_CH0_RVALID,
        in_HLS_RREADY          => I_CH0_RREADY,
        STD_LOGIC_VECTOR(out_HLS_RDATA)    => I_CH0_RDATA,
        STD_LOGIC_VECTOR(out_HLS_RFIFONUM) => I_CH0_RFIFONUM );
    -- load_unit for channel 1
    load_unit_1 : vertex_map_gmem_m_axi_load_with_cache
    generic map(
        C_TARGET_ADDR          => C_TARGET_ADDR,
        C_M_AXI_ID_WIDTH       => C_M_AXI_ID_WIDTH,
        C_ID_VALUE             => 2,
        NUM_READ_OUTSTANDING   => CH1_NUM_READ_OUTSTANDING,
        MAX_READ_BURST_LENGTH  => MAX_READ_BURST_LENGTH,
        BUS_ADDR_WIDTH         => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH         => C_M_AXI_DATA_WIDTH,
        USER_DW                => CH1_USER_DW,
        USER_AW                => CH1_USER_AW,
        USER_MAXREQS           => USER_MAXREQS,
        USER_RFIFONUM_WIDTH    => CH1_USER_RFIFONUM_WIDTH,
        NUM_CACHE_LINE         => CH1_NUM_CACHE_LINE,
        CACHE_LINE_DEPTH       => CH1_CACHE_LINE_DEPTH,
        CACHE_IMPL             => CH1_MAXI_CACHE_IMPL)
    port map(
        ACLK                   => ACLK,
        ARESET                 => ARESET,
        ACLK_EN                => ACLK_EN,
        cache_flush            => cache_flush,
        cache_flush_done       => open,
        out_AXI_ARID           => AXI_ARID_FromChanToArbiter(2),
        out_AXI_ARADDR         => AXI_ARADDR_FromChanToArbiter(2),
        out_AXI_ARLEN          => AXI_ARLEN_FromChanToArbiter(2),
        out_AXI_ARVALID        => AXI_ARVALID_FromChanToArbiter(2),
        in_AXI_ARREADY         => AXI_ARREADY_FromArbiterToChan(2),
        in_AXI_RID             => RID_FromBusToChan,
        in_AXI_RDATA           => RDATA_ToChan,
        in_AXI_RLAST           => RLAST_ToChan,
        in_AXI_RVALID          => RVALID_ToChan,
        out_AXI_RREADY         => RREADY_FromChan(2),
        out_AXI_RBURST_READY   => RBURST_READY_FromChan(2),
        in_HLS_ARADDR          => UNSIGNED(I_CH1_ARADDR),
        in_HLS_ARLEN           => UNSIGNED(I_CH1_ARLEN),
        in_HLS_ARVALID         => I_CH1_ARVALID,
        out_HLS_ARREADY        => I_CH1_ARREADY,
        out_HLS_RVALID         => I_CH1_RVALID,
        in_HLS_RREADY          => I_CH1_RREADY,
        STD_LOGIC_VECTOR(out_HLS_RDATA)    => I_CH1_RDATA,
        STD_LOGIC_VECTOR(out_HLS_RFIFONUM) => I_CH1_RFIFONUM );
    -- load_unit for channel 2
    load_unit_2 : vertex_map_gmem_m_axi_load_with_cache
    generic map(
        C_TARGET_ADDR          => C_TARGET_ADDR,
        C_M_AXI_ID_WIDTH       => C_M_AXI_ID_WIDTH,
        C_ID_VALUE             => 3,
        NUM_READ_OUTSTANDING   => CH2_NUM_READ_OUTSTANDING,
        MAX_READ_BURST_LENGTH  => MAX_READ_BURST_LENGTH,
        BUS_ADDR_WIDTH         => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH         => C_M_AXI_DATA_WIDTH,
        USER_DW                => CH2_USER_DW,
        USER_AW                => CH2_USER_AW,
        USER_MAXREQS           => USER_MAXREQS,
        USER_RFIFONUM_WIDTH    => CH2_USER_RFIFONUM_WIDTH,
        NUM_CACHE_LINE         => CH2_NUM_CACHE_LINE,
        CACHE_LINE_DEPTH       => CH2_CACHE_LINE_DEPTH,
        CACHE_IMPL             => CH2_MAXI_CACHE_IMPL)
    port map(
        ACLK                   => ACLK,
        ARESET                 => ARESET,
        ACLK_EN                => ACLK_EN,
        cache_flush            => cache_flush,
        cache_flush_done       => open,
        out_AXI_ARID           => AXI_ARID_FromChanToArbiter(3),
        out_AXI_ARADDR         => AXI_ARADDR_FromChanToArbiter(3),
        out_AXI_ARLEN          => AXI_ARLEN_FromChanToArbiter(3),
        out_AXI_ARVALID        => AXI_ARVALID_FromChanToArbiter(3),
        in_AXI_ARREADY         => AXI_ARREADY_FromArbiterToChan(3),
        in_AXI_RID             => RID_FromBusToChan,
        in_AXI_RDATA           => RDATA_ToChan,
        in_AXI_RLAST           => RLAST_ToChan,
        in_AXI_RVALID          => RVALID_ToChan,
        out_AXI_RREADY         => RREADY_FromChan(3),
        out_AXI_RBURST_READY   => RBURST_READY_FromChan(3),
        in_HLS_ARADDR          => UNSIGNED(I_CH2_ARADDR),
        in_HLS_ARLEN           => UNSIGNED(I_CH2_ARLEN),
        in_HLS_ARVALID         => I_CH2_ARVALID,
        out_HLS_ARREADY        => I_CH2_ARREADY,
        out_HLS_RVALID         => I_CH2_RVALID,
        in_HLS_RREADY          => I_CH2_RREADY,
        STD_LOGIC_VECTOR(out_HLS_RDATA)    => I_CH2_RDATA,
        STD_LOGIC_VECTOR(out_HLS_RFIFONUM) => I_CH2_RFIFONUM );
    -- load_unit for channel 5
    load_unit_5 : vertex_map_gmem_m_axi_load
    generic map(
        C_TARGET_ADDR          => C_TARGET_ADDR,
        C_M_AXI_ID_WIDTH       => C_M_AXI_ID_WIDTH,
        C_ID_VALUE             => 0,
        NUM_READ_OUTSTANDING   => CH5_NUM_READ_OUTSTANDING,
        MAX_READ_BURST_LENGTH  => MAX_READ_BURST_LENGTH,
        BUS_ADDR_WIDTH         => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH         => C_M_AXI_DATA_WIDTH,
        USER_DW                => CH5_USER_DW,
        USER_AW                => CH5_USER_AW,
        USER_MAXREQS           => USER_MAXREQS,
        USER_RFIFONUM_WIDTH    => CH5_USER_RFIFONUM_WIDTH,
        BUFFER_IMPL            => MAXI_BUFFER_IMPL)
    port map(
        ACLK                   => ACLK,
        ARESET                 => ARESET,
        ACLK_EN                => ACLK_EN,
        out_AXI_ARID           => AXI_ARID_FromChanToArbiter(0),
        out_AXI_ARADDR         => AXI_ARADDR_FromChanToArbiter(0),
        out_AXI_ARLEN          => AXI_ARLEN_FromChanToArbiter(0),
        out_AXI_ARVALID        => AXI_ARVALID_FromChanToArbiter(0),
        in_AXI_ARREADY         => AXI_ARREADY_FromArbiterToChan(0),
        in_AXI_RID             => RID_FromBusToChan,
        in_AXI_RDATA           => RDATA_ToChan,
        in_AXI_RLAST           => RLAST_ToChan,
        in_AXI_RVALID          => RVALID_ToChan,
        out_AXI_RREADY         => RREADY_FromChan(0),
        out_AXI_RBURST_READY   => RBURST_READY_FromChan(0),
        in_HLS_ARADDR          => UNSIGNED(I_CH5_ARADDR),
        in_HLS_ARLEN           => UNSIGNED(I_CH5_ARLEN),
        in_HLS_ARVALID         => I_CH5_ARVALID,
        out_HLS_ARREADY        => I_CH5_ARREADY,
        out_HLS_RVALID         => I_CH5_RVALID,
        in_HLS_RREADY          => I_CH5_RREADY,
        STD_LOGIC_VECTOR(out_HLS_RDATA)    => I_CH5_RDATA,
        STD_LOGIC_VECTOR(out_HLS_RFIFONUM) => I_CH5_RFIFONUM ); 
    -- arbiter for all load channels
    load_arbiter : vertex_map_gmem_m_axi_arbiter
    generic map (
        STRATEGY    => "load_balance",
        PORTS       => NUM_READ_PORTS,
        PORTS_WIDTH => C_M_AXI_ID_WIDTH)
    port map (
        clk         => ACLK,
        reset       => ARESET,
        s_ready     => ARREADY_ToArbiter,
        s_valid     => ARVALID_FromArbiter,
        s_index     => arid_index,
        m_ready     => AXI_ARREADY_FromArbiterToChan,
        m_valid     => AXI_ARVALID_FromChanToArbiter);

    -- ++++++++++++++++++++++ AXI BUS READ/WRITE ++++++++++++++++++++++ 
    -- vertex_map_gmem_m_axi_write
    bus_write : vertex_map_gmem_m_axi_write
    generic map (
        CONSERVATIVE                       => CONSERVATIVE,
        C_M_AXI_ID_WIDTH                   => C_M_AXI_ID_WIDTH,
        C_M_AXI_AWUSER_WIDTH               => C_M_AXI_AWUSER_WIDTH,
        C_M_AXI_WUSER_WIDTH                => C_M_AXI_WUSER_WIDTH,
        C_M_AXI_BUSER_WIDTH                => C_M_AXI_BUSER_WIDTH,
        C_USER_VALUE                       => C_USER_VALUE,
        C_PROT_VALUE                       => C_PROT_VALUE,
        C_CACHE_VALUE                      => C_CACHE_VALUE,
        BUS_ADDR_WIDTH                     => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH                     => C_M_AXI_DATA_WIDTH,
        MAX_WRITE_BURST_LENGTH             => MAX_WRITE_BURST_LENGTH,
        NUM_WRITE_OUTSTANDING              => NUM_WRITE_OUTSTANDING,
        -- outstanding control for channels
        ID0_NUM_WRITE_OUTSTANDING          => CH5_NUM_WRITE_OUTSTANDING,
        NUM_WRITE_PORTS                    => NUM_WRITE_PORTS)
    port map (
        ACLK                               => ACLK,
        ARESET                             => ARESET,
        ACLK_EN                            => ACLK_EN,
        STD_LOGIC_VECTOR(out_BUS_AWID)     => AWID,
        STD_LOGIC_VECTOR(out_BUS_AWADDR)   => AWADDR,
        STD_LOGIC_VECTOR(out_BUS_AWLEN)    => AWLEN,
        STD_LOGIC_VECTOR(out_BUS_AWSIZE)   => AWSIZE,
        STD_LOGIC_VECTOR(out_BUS_AWBURST)  => AWBURST,
        STD_LOGIC_VECTOR(out_BUS_AWLOCK)   => AWLOCK,
        STD_LOGIC_VECTOR(out_BUS_AWCACHE)  => AWCACHE,
        STD_LOGIC_VECTOR(out_BUS_AWPROT)   => AWPROT,
        STD_LOGIC_VECTOR(out_BUS_AWQOS)    => AWQOS,
        STD_LOGIC_VECTOR(out_BUS_AWREGION) => AWREGION,
        STD_LOGIC_VECTOR(out_BUS_AWUSER)   => AWUSER,
        out_BUS_AWVALID                    => AWVALID ,
        in_BUS_AWREADY                     => AWREADY ,
        STD_LOGIC_VECTOR(out_BUS_WID)      => WID,
        STD_LOGIC_VECTOR(out_BUS_WDATA)    => WDATA,
        STD_LOGIC_VECTOR(out_BUS_WSTRB)    => WSTRB,
        out_BUS_WLAST                      => WLAST,
        STD_LOGIC_VECTOR(out_BUS_WUSER)    => WUSER,
        out_BUS_WVALID                     => WVALID ,
        in_BUS_WREADY                      => WREADY,
        in_BUS_BID                         => UNSIGNED(BID),
        in_BUS_BRESP                       => UNSIGNED(BRESP),
        in_BUS_BUSER                       => UNSIGNED(BUSER),
        in_BUS_BVALID                      => BVALID,
        out_BUS_BREADY                     => BREADY ,
        in_AXI_AWID                        => AWID_FromArbiterToBus,
        in_AXI_AWVALID                     => AWVALID_FromArbiterToBus,
        out_AXI_AWREADY                    => AWREADY_FromBusToArbiter,
        in_AXI_AWADDR                      => AWADDR_FromArbiterToBus,
        in_AXI_AWLEN                       => AWLEN_FromArbiterToBus,
        in_AXI_BURST_REQ                   => BURST_REQ_FromChanToBus,
        out_AXI_BURST_ID                   => BURST_ID_FromBusToChan,
        out_AXI_BURST_LEN                  => BURST_LEN_FromBusToChan,
        out_AXI_BURST_ACK                  => BURST_ACK_FromBusToChan,
        out_AXI_WID                        => WID_FromBusToArbiter,
        in_AXI_WVALID                      => WVALID_FromArbiterToBus,
        out_AXI_WREADY                     => WREADY_FromBusToArbiter,
        in_AXI_WSTRB                       => WSTRB_FromArbiterToBus,
        in_AXI_WDATA                       => WDATA_FromArbiterToBus,
        out_AXI_BID                        => BID_FromBusToChan,
        out_AXI_BVALID                     => BVALID_FromBusToChan,
        in_AXI_BREADY                      => BREADY_FromChanToBus);
    -- vertex_map_gmem_m_axi_read
    bus_read : vertex_map_gmem_m_axi_read
    generic map (
        C_M_AXI_ID_WIDTH                   => C_M_AXI_ID_WIDTH,
        C_M_AXI_ARUSER_WIDTH               => C_M_AXI_ARUSER_WIDTH,
        C_M_AXI_RUSER_WIDTH                => C_M_AXI_RUSER_WIDTH,
        C_USER_VALUE                       => C_USER_VALUE,
        C_PROT_VALUE                       => C_PROT_VALUE,
        C_CACHE_VALUE                      => C_CACHE_VALUE,
        BUS_ADDR_WIDTH                     => C_M_AXI_ADDR_WIDTH,
        BUS_DATA_WIDTH                     => C_M_AXI_DATA_WIDTH,
        MAX_READ_BURST_LENGTH              => MAX_READ_BURST_LENGTH,
        NUM_READ_OUTSTANDING               => NUM_READ_OUTSTANDING,
        -- outstanding control for channels
        ID1_NUM_READ_OUTSTANDING           => CH0_NUM_READ_OUTSTANDING, 
        ID2_NUM_READ_OUTSTANDING           => CH1_NUM_READ_OUTSTANDING, 
        ID3_NUM_READ_OUTSTANDING           => CH2_NUM_READ_OUTSTANDING, 
        ID0_NUM_READ_OUTSTANDING           => CH5_NUM_READ_OUTSTANDING, 
        NUM_READ_PORTS                     =>  NUM_READ_PORTS )
    port map (
        ACLK                               => ACLK,
        ARESET                             => ARESET,
        ACLK_EN                            => ACLK_EN,
        STD_LOGIC_VECTOR(out_BUS_ARID)     => ARID,
        STD_LOGIC_VECTOR(out_BUS_ARADDR)   => ARADDR,
        STD_LOGIC_VECTOR(out_BUS_ARLEN)    => ARLEN,
        STD_LOGIC_VECTOR(out_BUS_ARSIZE)   => ARSIZE,
        STD_LOGIC_VECTOR(out_BUS_ARBURST)  => ARBURST,
        STD_LOGIC_VECTOR(out_BUS_ARLOCK)   => ARLOCK,
        STD_LOGIC_VECTOR(out_BUS_ARCACHE)  => ARCACHE,
        STD_LOGIC_VECTOR(out_BUS_ARPROT)   => ARPROT,
        STD_LOGIC_VECTOR(out_BUS_ARQOS)    => ARQOS,
        STD_LOGIC_VECTOR(out_BUS_ARREGION) => ARREGION,
        STD_LOGIC_VECTOR(out_BUS_ARUSER)   => ARUSER,
        out_BUS_ARVALID                    => ARVALID ,
        in_BUS_ARREADY                     => ARREADY,
        in_BUS_RID                         => UNSIGNED(RID),
        in_BUS_RDATA                       => UNSIGNED(RDATA),
        in_BUS_RRESP                       => UNSIGNED(RRESP),
        in_BUS_RLAST                       => RLAST,
        in_BUS_RUSER                       => UNSIGNED(RUSER),
        in_BUS_RVALID                      => RVALID,
        out_BUS_RREADY                     => RREADY,
        in_AXI_ARID                        => ARID_FromArbiterToBus,
        in_AXI_ARVALID                     => ARVALID_ToBus,
        out_AXI_ARREADY                    => ARREADY_FromBus,
        in_AXI_ARADDR                      => ARADDR_ToBus,
        in_AXI_ARLEN                       => ARLEN_ToBus,
        out_AXI_RID                        => RID_FromBusToChan,
        out_AXI_RVALID                     => RVALID_FromBus,
        in_AXI_RREADY                      => RREADY_ToBus,
        in_AXI_RBURST_READY                => RBURST_READY_ToBus,
        out_AXI_RDATA                      => RDATA_FromBus,
        out_AXI_RLAST                      => RLAST_FromBus
        );
        
        ARREADY_ToArbiter  <= ARREADY_FromBus;
        ARADDR_ToBus       <= ARADDR_FromArbiter;
        ARLEN_ToBus        <= ARLEN_FromArbiter;
        ARVALID_ToBus      <= ARVALID_FromArbiter;

        RDATA_ToChan       <= RDATA_FromBus;
        RLAST_ToChan       <= RLAST_FromBus;
        RVALID_ToChan      <= RVALID_FromBus;
        RREADY_ToBus       <= RREADY_FromChan;
        RBURST_READY_ToBus <= RBURST_READY_FromChan;
        

    
end architecture behave;


-- 67d7842dbbe25473c3c32b93c0da8047785f30d78e8a024de1b57352245f9689

library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_load is
    generic (
        C_TARGET_ADDR         : INTEGER := 16#00000000#;
        C_M_AXI_ID_WIDTH      : INTEGER := 1;
        C_ID_VALUE            : INTEGER := 0;
        NUM_READ_OUTSTANDING  : INTEGER := 2;
        MAX_READ_BURST_LENGTH : INTEGER := 16;
        BUS_ADDR_WIDTH        : INTEGER := 32;
        BUS_DATA_WIDTH        : INTEGER := 32;
        USER_DW               : INTEGER := 16;
        USER_AW               : INTEGER := 32;
        USER_MAXREQS          : INTEGER := 16;
        USER_RFIFONUM_WIDTH   : INTEGER := 6;
        BUFFER_IMPL           : STRING  := "auto");
    port (
        ACLK                  : in  STD_LOGIC;
        ARESET                : in  STD_LOGIC;
        ACLK_EN               : in  STD_LOGIC;

        out_AXI_ARID          : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        out_AXI_ARADDR        : out UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);
        out_AXI_ARLEN         : out UNSIGNED(31 downto 0);
        out_AXI_ARVALID       : out STD_LOGIC;
        in_AXI_ARREADY        : in  STD_LOGIC;
        in_AXI_RID            : in  UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        in_AXI_RDATA          : in  UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
        in_AXI_RLAST          : in  UNSIGNED(1 downto 0);
        in_AXI_RVALID         : in  STD_LOGIC;
        out_AXI_RREADY        : out STD_LOGIC;
        out_AXI_RBURST_READY  : out STD_LOGIC;
        
        in_HLS_ARADDR         : in  UNSIGNED(USER_AW-1 downto 0);
        in_HLS_ARLEN          : in  UNSIGNED(31 downto 0);
        in_HLS_ARVALID        : in  STD_LOGIC;
        out_HLS_ARREADY       : out STD_LOGIC;
        out_HLS_RDATA         : out UNSIGNED(USER_DW-1 downto 0);
        out_HLS_RVALID        : out STD_LOGIC;
        in_HLS_RREADY         : in  STD_LOGIC;
        out_HLS_RFIFONUM      : out UNSIGNED(USER_RFIFONUM_WIDTH-1 downto 0));
end entity vertex_map_gmem_m_axi_load;

architecture behave of vertex_map_gmem_m_axi_load is
    ------------------------Task and function--------------
    function calc_data_width (x : INTEGER) return INTEGER is
        variable y : INTEGER;
    begin
        y := 8;
        while y < x loop
            y := y * 2;
        end loop;
        return y;
    end function calc_data_width;

    function log2 (x : INTEGER) return INTEGER is
        variable n, m : INTEGER;
    begin
        n := 0;
        m := 1;
        while m < x loop
            n := n + 1;
            m := m * 2;
        end loop;
        return n;
    end function log2;
    ------------------------Parameter----------------------
    constant USER_DATA_WIDTH  : INTEGER := calc_data_width(USER_DW);
    constant USER_DATA_BYTES  : INTEGER := USER_DATA_WIDTH / 8;
    constant USER_ADDR_ALIGN  : INTEGER := log2(USER_DATA_BYTES);
    constant BUS_DATA_BYTES   : INTEGER := BUS_DATA_WIDTH / 8;
    constant BUS_ADDR_ALIGN   : INTEGER := log2(BUS_DATA_BYTES);
    -- rdata buffer size 
    constant RBUFF_DEPTH      : INTEGER := MAX_READ_BURST_LENGTH*NUM_READ_OUTSTANDING;
    constant TARGET_ADDR      : INTEGER := (C_TARGET_ADDR/USER_DATA_BYTES)*USER_DATA_BYTES;

    ------------------------Local signal-------------------
    signal next_rreq      : STD_LOGIC;
    signal ready_for_rreq : STD_LOGIC;
    signal rreq_ready     : STD_LOGIC;
    
    signal in_rreq_pack   : UNSIGNED(USER_AW+31 downto 0);
    signal rreq_pack      : UNSIGNED(USER_AW+31 downto 0);
    signal rreq_addr      : UNSIGNED(USER_AW-1 downto 0);
    signal rreq_len       : UNSIGNED(31 downto 0);
    signal rreq_valid     : STD_LOGIC;
    
    signal tmp_addr       : UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);
    signal tmp_len        : UNSIGNED(31 downto 0);
    signal tmp_valid      : STD_LOGIC;
    
    signal valid_length   : STD_LOGIC;
    
    signal beat_valid     : STD_LOGIC;
    signal next_beat      : STD_LOGIC;
    signal last_beat      : STD_LOGIC;
    signal beat_data      : UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
    signal in_beat_pack   : UNSIGNED(BUS_DATA_WIDTH+1 downto 0); 
    signal in_beat_valid  : STD_LOGIC;
    signal beat_pack      : UNSIGNED(BUS_DATA_WIDTH+1 downto 0);
    signal beat_nvalid    : UNSIGNED(log2(RBUFF_DEPTH) downto 0);
    signal burst_ready    : STD_LOGIC;
    signal ready_for_outstanding : STD_LOGIC; 

    -- regslice io ?  no 

    -- enable regslice on R channel  no 

    component vertex_map_gmem_m_axi_fifo is
        generic (
            MEM_STYLE         : STRING  := "shiftreg";
            DATA_WIDTH        : INTEGER := 8;
            ADDR_WIDTH        : INTEGER := 4;
            DEPTH             : INTEGER := 16);
        port (
            clk               : in  STD_LOGIC;
            reset             : in  STD_LOGIC;
            clk_en            : in  STD_LOGIC;
            if_full_n         : out STD_LOGIC;
            if_write          : in  STD_LOGIC;
            if_din            : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            if_empty_n        : out STD_LOGIC;
            if_read           : in  STD_LOGIC;
            if_dout           : out UNSIGNED(DATA_WIDTH-1 downto 0);
            if_num_data_valid : out UNSIGNED(ADDR_WIDTH downto 0));
    end component vertex_map_gmem_m_axi_fifo;

    component vertex_map_gmem_m_axi_reg_slice is
        generic (
            DATA_WIDTH  : INTEGER := 8);
        port (
            clk         : in  STD_LOGIC;
            reset       : in  STD_LOGIC;
            s_data      : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            s_valid     : in  STD_LOGIC;
            s_ready     : out STD_LOGIC;
            m_data      : out UNSIGNED(DATA_WIDTH-1 downto 0);
            m_valid     : out STD_LOGIC;
            m_ready     : in  STD_LOGIC);
    end component vertex_map_gmem_m_axi_reg_slice;

begin

    -- Instantiation
    
    
    fifo_rreq : vertex_map_gmem_m_axi_fifo
    generic map (
        DATA_WIDTH        => USER_AW + 32,
        ADDR_WIDTH        => log2(USER_MAXREQS),
        DEPTH             => USER_MAXREQS)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => out_HLS_ARREADY,
        if_write          => in_HLS_ARVALID,
        if_din            => in_rreq_pack,
        if_empty_n        => rreq_valid,
        if_read           => next_rreq,
        if_dout           => rreq_pack,
        if_num_data_valid => open);

    -- ===================================================================
    -- start of ARADDR PREPROCESSOR
    in_rreq_pack    <= in_HLS_ARLEN & in_HLS_ARADDR;
    next_rreq       <= rreq_valid and ready_for_rreq;
    ready_for_rreq  <= (not tmp_valid) or (in_AXI_ARREADY and rreq_ready);
    rreq_len        <= rreq_pack(USER_AW + 31 downto USER_AW);
    rreq_addr       <= rreq_pack(USER_AW - 1 downto 0);

    valid_length    <= '1' when rreq_len /= 0 and rreq_len(31) = '0' else '0';

    out_AXI_ARID    <= TO_UNSIGNED(C_ID_VALUE, C_M_AXI_ID_WIDTH);
    out_AXI_ARLEN   <= tmp_len;   -- Byte length
    out_AXI_ARADDR  <= tmp_addr;  -- Byte address
    out_AXI_ARVALID <= tmp_valid and rreq_ready;

    process (ACLK)
    begin
        if (ACLK'event and ACLK = '1') then
            if (ARESET = '1') then
                tmp_addr <= (others => '0');
                tmp_len   <= (others => '0');
            elsif ACLK_EN = '1' then
                if (next_rreq = '1') then
                    tmp_addr  <= TARGET_ADDR + SHIFT_LEFT(RESIZE(rreq_addr, BUS_ADDR_WIDTH), USER_ADDR_ALIGN);
                    tmp_len   <= SHIFT_LEFT(rreq_len, USER_ADDR_ALIGN) - 1;
                end if;
            end if;
        end if;
    end process;

    process (ACLK)
    begin
        if (ACLK'event and ACLK = '1') then
            if (ARESET = '1') then
                tmp_valid  <= '0';
            elsif ACLK_EN = '1' then
                if (next_rreq and valid_length) = '1' then
                    tmp_valid <= '1';
                elsif (in_AXI_ARREADY and rreq_ready) = '1' then
                    tmp_valid <= '0';
                end if;
            end if;
        end if;
    end process;

    -- end of ARADDR PREPROCESSOR
    -- ===================================================================
    
    

    
    buff_rdata : vertex_map_gmem_m_axi_fifo
    generic map (
        MEM_STYLE         => BUFFER_IMPL,
        DATA_WIDTH        => BUS_DATA_WIDTH + 2,
        ADDR_WIDTH        => log2(RBUFF_DEPTH),
        DEPTH             => RBUFF_DEPTH)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => out_AXI_RREADY,
        if_write          => in_beat_valid,
        if_din            => in_beat_pack,
        if_empty_n        => beat_valid,
        if_read           => next_beat,
        if_dout           => beat_pack,
        if_num_data_valid => beat_nvalid);
        
        in_beat_pack     <= in_AXI_RLAST & in_AXI_RDATA;
        in_beat_valid    <= '1' when (in_AXI_RVALID = '1') and (in_AXI_RID = C_ID_VALUE) else '0';
        beat_data        <= beat_pack(BUS_DATA_WIDTH-1 downto 0);
        last_beat        <= beat_pack(BUS_DATA_WIDTH);
        burst_ready      <= beat_pack(BUS_DATA_WIDTH+1);

        out_AXI_RBURST_READY <= ready_for_outstanding;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    ready_for_outstanding  <= '1';
                elsif ACLK_EN = '1' then
                    if (next_beat = '1' and beat_valid = '1') then
                        ready_for_outstanding <= burst_ready;
                    else
                        ready_for_outstanding <= '0';
                    end if;
                end if;
            end if;
        end process;

    -- ===================================================================
    -- start of RDATA PREPROCESSOR
    bus_equal_gen : if (USER_DATA_WIDTH = BUS_DATA_WIDTH) generate
    begin
        rreq_ready       <= '1';
        -- regslice io ?  no
        next_beat        <= in_HLS_RREADY;
        out_HLS_RDATA    <= beat_data(USER_DW-1 downto 0);
        out_HLS_RVALID   <= beat_valid;
        out_HLS_RFIFONUM <= RESIZE(beat_nvalid, USER_RFIFONUM_WIDTH); -- 

    end generate bus_equal_gen;

    bus_wide_gen : if (USER_DATA_WIDTH < BUS_DATA_WIDTH) generate
        constant TOTAL_SPLIT    : INTEGER := BUS_DATA_WIDTH / USER_DATA_WIDTH;
        constant SPLIT_ALIGN    : INTEGER := log2(TOTAL_SPLIT);
        signal  tmp_addr_end    : UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);

        signal  offset_full_n   : STD_LOGIC;
        signal  offset_write    : STD_LOGIC;
        signal  start_offset    : UNSIGNED(SPLIT_ALIGN-1 downto 0);
        signal  end_offset      : UNSIGNED(SPLIT_ALIGN-1 downto 0);

        signal  offset_valid    : STD_LOGIC;
        signal  next_offset     : STD_LOGIC;
        signal  offset_info     : UNSIGNED(2*SPLIT_ALIGN-1 downto 0);
        signal  offset_pack     : UNSIGNED(2*SPLIT_ALIGN-1 downto 0);
        signal  head_offset     : UNSIGNED(SPLIT_ALIGN-1 downto 0);
        signal  tail_offset     : UNSIGNED(SPLIT_ALIGN-1 downto 0);

        signal  tmp_rdata_pack  : UNSIGNED(BUS_DATA_WIDTH downto 0);
        signal  tmp_rdata       : UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
        signal  tmp_rlast       : STD_LOGIC;
        signal  tmp_rvalid      : STD_LOGIC;
        signal  tmp_rready      : STD_LOGIC;

        signal  data_buf        : UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
        signal  data_valid      : STD_LOGIC;

        signal  rdata_nvalid    : UNSIGNED(USER_RFIFONUM_WIDTH-1 downto 0);
        signal  data_nvalid     : UNSIGNED(SPLIT_ALIGN downto 0);
        signal  split_nvalid    : UNSIGNED(SPLIT_ALIGN downto 0);

        signal  split_cnt_end   : UNSIGNED(SPLIT_ALIGN-1 downto 0);
        signal  split_cnt       : UNSIGNED(SPLIT_ALIGN-1 downto 0);
        signal  split_cnt_buf   : UNSIGNED(SPLIT_ALIGN-1 downto 0);

        signal  first_beat      : STD_LOGIC;

        signal  ready_for_data  : BOOLEAN;
        signal  first_data      : BOOLEAN;
        signal  last_data       : BOOLEAN;
        
        signal  ready_for_split : BOOLEAN;
        signal  first_split     : BOOLEAN;
        signal  next_split      : BOOLEAN;
        signal  last_split      : BOOLEAN;

    begin

        rreq_offset : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => 2*SPLIT_ALIGN,
            ADDR_WIDTH        => log2(NUM_READ_OUTSTANDING),
            DEPTH             => NUM_READ_OUTSTANDING)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            clk_en            => ACLK_EN,
            if_full_n         => offset_full_n,
            if_write          => offset_write,
            if_din            => offset_info,
            if_empty_n        => offset_valid,
            if_read           => next_offset,
            if_dout           => offset_pack,
            if_num_data_valid => open);

        rs_tmp_rdata : vertex_map_gmem_m_axi_reg_slice
        generic map (
            DATA_WIDTH        => BUS_DATA_WIDTH + 1)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            s_data            => beat_pack(BUS_DATA_WIDTH downto 0),
            s_valid           => beat_valid,
            s_ready           => next_beat,
            m_data            => tmp_rdata_pack,
            m_valid           => tmp_rvalid,
            m_ready           => tmp_rready);

        rreq_ready       <= '1' when offset_full_n = '1' or offset_write = '0' else '0';
        tmp_addr_end     <= tmp_addr + tmp_len;

        start_offset     <= tmp_addr(BUS_ADDR_ALIGN-1 downto USER_ADDR_ALIGN);
        end_offset       <= tmp_addr_end(BUS_ADDR_ALIGN-1 downto USER_ADDR_ALIGN);
        offset_info      <= start_offset & end_offset;
        offset_write     <= tmp_valid and in_AXI_ARREADY;

        next_offset      <= (tmp_rlast and tmp_rvalid) and tmp_rready;
        head_offset      <= offset_pack(2*SPLIT_ALIGN-1 downto SPLIT_ALIGN);
        tail_offset      <= offset_pack(SPLIT_ALIGN-1 downto 0);

        tmp_rready       <= '1' when last_split else '0';
        tmp_rlast        <= tmp_rdata_pack(BUS_DATA_WIDTH);
        tmp_rdata        <= tmp_rdata_pack(BUS_DATA_WIDTH-1 downto 0);

        -- regslice io ?  no
        out_HLS_RDATA    <= data_buf(USER_DW-1 downto 0);
        out_HLS_RVALID   <= data_valid;
        out_HLS_RFIFONUM <= rdata_nvalid + data_nvalid;
        ready_for_data   <= data_valid = '0' or in_HLS_RREADY = '1'; -- 

        first_data       <= (first_beat = '1') and ready_for_split;
        last_data        <= (tmp_rlast = '1')  and ready_for_split;

        ready_for_split  <= (tmp_rvalid and offset_valid) = '1';
        next_split       <= ready_for_split and ready_for_data;

        first_split      <= (split_cnt_buf = 0) and next_split;
        last_split       <= (split_cnt = split_cnt_end) and next_split;

        split_cnt        <= head_offset when first_data and (split_cnt_buf = 0) else
                            split_cnt_buf;
        split_cnt_end    <= tail_offset when last_data else
                            TO_UNSIGNED(TOTAL_SPLIT - 1, SPLIT_ALIGN);

        split_nvalid     <= RESIZE(tail_offset, SPLIT_ALIGN+1) - head_offset + 1  when first_data and last_data else
                            RESIZE(tail_offset, SPLIT_ALIGN+1) + 1                when last_data                else
                            TO_UNSIGNED(TOTAL_SPLIT, SPLIT_ALIGN+1) - head_offset when first_data               else
                            TO_UNSIGNED(TOTAL_SPLIT, SPLIT_ALIGN+1);

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    first_beat <= '1';
                elsif ACLK_EN = '1' then
                    if next_offset = '1' then
                        first_beat <= '1';
                    elsif (first_beat = '1' and last_split) then
                        first_beat <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    split_cnt_buf <= (others => '0');
                elsif ACLK_EN = '1' then
                    if last_split then
                        split_cnt_buf <= (others => '0');
                    elsif next_split then
                        split_cnt_buf <= split_cnt + 1;
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if ACLK_EN = '1' then
                    if first_split and first_data then
                        data_buf <= SHIFT_RIGHT(tmp_rdata, to_integer(head_offset)*USER_DATA_WIDTH);
                    elsif first_split then
                        data_buf <= tmp_rdata;
                    elsif next_split then
                        data_buf <= SHIFT_RIGHT(data_buf, USER_DATA_WIDTH);
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_valid <= '0';
                elsif ACLK_EN = '1' then
                    if first_split then
                        data_valid <= '1';
                    elsif not ready_for_split and ready_for_data then
                        data_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_nvalid <= (others=>'0');
                elsif ACLK_EN = '1' then
                    if first_split then
                        data_nvalid <= split_nvalid;
                    elsif next_split then
                        data_nvalid <= data_nvalid - 1;
                    elsif not ready_for_split and ready_for_data then
                        data_nvalid <= (others=>'0');
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    rdata_nvalid <= (others=>'0');
                elsif ACLK_EN = '1' then
                    if tmp_rvalid = '0' then
                        rdata_nvalid <= (others=>'0');
                    elsif next_beat = '0' then 
                        rdata_nvalid <= SHIFT_LEFT(RESIZE(beat_nvalid+1, USER_RFIFONUM_WIDTH), SPLIT_ALIGN);
                    else
                        rdata_nvalid <= SHIFT_LEFT(RESIZE(beat_nvalid, USER_RFIFONUM_WIDTH), SPLIT_ALIGN);
                    end if;
                end if;
            end if;
        end process;

    end generate bus_wide_gen; 

    bus_narrow_gen : if (USER_DATA_WIDTH > BUS_DATA_WIDTH) generate
        constant TOTAL_PADS     : INTEGER := USER_DATA_WIDTH / BUS_DATA_WIDTH;
        constant PAD_ALIGN      : INTEGER := log2(TOTAL_PADS);

        signal  data_buf        : UNSIGNED(USER_DATA_WIDTH-1 downto 0);
        signal  data_nvalid     : UNSIGNED(PAD_ALIGN downto 0);
        signal  data_valid      : STD_LOGIC;
        signal  pad_oh          : UNSIGNED(TOTAL_PADS - 1 downto 0);
        signal  pad_oh_reg      : UNSIGNED(TOTAL_PADS - 1 downto 0);
       
        signal  rdata_num_vld   : UNSIGNED(USER_RFIFONUM_WIDTH - 1 downto 0);
        signal  ready_for_data  : BOOLEAN;
        signal  next_pad        : BOOLEAN;
        signal  first_pad       : BOOLEAN;
        signal  last_pad        : BOOLEAN;
    begin

        rreq_ready       <= '1';
        next_beat        <= '1' when next_pad else '0';
        rdata_num_vld    <= RESIZE(beat_nvalid(log2(RBUFF_DEPTH) downto PAD_ALIGN), RBUFF_DEPTH) + SHIFT_RIGHT(beat_nvalid(PAD_ALIGN-1 downto 0) + data_nvalid, PAD_ALIGN);

        -- regslice io ?  no
        out_HLS_RDATA    <= data_buf(USER_DW-1 downto 0);
        out_HLS_RVALID   <= data_valid;
        out_HLS_RFIFONUM <= rdata_num_vld;
        ready_for_data   <= data_valid = '0' or in_HLS_RREADY = '1';-- 

        next_pad         <= beat_valid = '1' and ready_for_data;
        last_pad         <= pad_oh(TOTAL_PADS - 1) = '1';

        pad_oh           <= (others => '0')            when beat_valid = '0' else
                            TO_UNSIGNED(1, TOTAL_PADS) when first_pad      else
                            pad_oh_reg;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    pad_oh_reg <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_pad then
                        pad_oh_reg <= pad_oh(TOTAL_PADS - 2 downto 0) & '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    first_pad <= true;
                elsif ACLK_EN = '1' then
                    if next_pad and not last_pad then
                        first_pad <= false;
                    elsif next_pad and last_pad then
                        first_pad <= true;
                    end if;
                end if;
            end if;
        end process;

        data_gen : for i in 0 to TOTAL_PADS-1 generate
        begin
            process (ACLK)
            begin
                if (ACLK'event and ACLK = '1') then
                    if ACLK_EN = '1' then
                        if pad_oh(i) = '1' and ready_for_data then
                            data_buf((i+1)*BUS_DATA_WIDTH - 1 downto i*BUS_DATA_WIDTH) <= beat_data;
                        end if;
                    end if;
                end if;
            end process;
        end generate data_gen;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_valid <= '0';
                elsif ACLK_EN = '1' then
                    if next_beat = '1' then
                        data_valid <= '1';
                    elsif ready_for_data then
                        data_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_nvalid <= (others=>'0');
                elsif ACLK_EN = '1' then
                    if first_pad then
                        data_nvalid <= TO_UNSIGNED(1,PAD_ALIGN+1);
                    elsif next_pad then
                        data_nvalid <= data_nvalid + 1;
                    end if;
                end if;
            end if;
        end process;
    
    end generate bus_narrow_gen;

    -- end of RDATA PREPROCESSOR
    -- ==================================================================

end architecture behave;

library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_store is
    generic (
        C_TARGET_ADDR          : INTEGER := 16#00000000#;
        C_M_AXI_ID_WIDTH       : INTEGER := 1;
        C_ID_VALUE             : INTEGER := 0;
        NUM_WRITE_OUTSTANDING  : INTEGER := 2;
        MAX_WRITE_BURST_LENGTH : INTEGER := 16;
        BUS_ADDR_WIDTH         : INTEGER := 32;
        BUS_DATA_WIDTH         : INTEGER := 32;
        USER_DW                : INTEGER := 16;
        USER_AW                : INTEGER := 32;
        USER_MAXREQS           : INTEGER := 16;
        BUFFER_IMPL            : STRING  := "auto"); 
    port (
        ACLK                   : in  STD_LOGIC;
        ARESET                 : in  STD_LOGIC;
        ACLK_EN                : in  STD_LOGIC;

        out_AXI_AWID           : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        out_AXI_AWADDR         : out UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);
        out_AXI_AWLEN          : out UNSIGNED(31 downto 0);
        out_AXI_AWVALID        : out STD_LOGIC;
        in_AXI_AWREADY         : in  STD_LOGIC;
        out_AXI_BURST_REQ      : out STD_LOGIC;
        in_AXI_BURST_ID        : in  UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        in_AXI_BURST_LEN       : in  UNSIGNED(7 downto 0);
        in_AXI_BURST_ACK       : in  STD_LOGIC;
        out_AXI_WID            : out UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        out_AXI_WDATA          : out UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
        out_AXI_WSTRB          : out UNSIGNED(BUS_DATA_WIDTH/8-1 downto 0);
        out_AXI_WVALID         : out STD_LOGIC;
        in_AXI_WREADY          : in  STD_LOGIC;
        in_AXI_BID             : in  UNSIGNED(C_M_AXI_ID_WIDTH-1 downto 0);
        in_AXI_BVALID          : in  STD_LOGIC;
        out_AXI_BREADY         : out STD_LOGIC;
    
        in_HLS_AWADDR          : in  UNSIGNED(USER_AW-1 downto 0);
        in_HLS_AWLEN           : in  UNSIGNED(31 downto 0); 
        in_HLS_AWVALID         : in  STD_LOGIC;
        out_HLS_AWREADY        : out STD_LOGIC;
        in_HLS_WDATA           : in  UNSIGNED(USER_DW-1 downto 0);
        in_HLS_WSTRB           : in  UNSIGNED(USER_DW/8-1 downto 0);
        in_HLS_WVALID          : in  STD_LOGIC;
        out_HLS_WREADY         : out STD_LOGIC;
        out_HLS_BVALID         : out STD_LOGIC;
        in_HLS_BREADY          : in  STD_LOGIC);
end entity vertex_map_gmem_m_axi_store;

architecture behave of vertex_map_gmem_m_axi_store is
    ------------------------Task and function--------------
    function max (x : INTEGER; 
                  y : INTEGER) return INTEGER is
        variable r : INTEGER;
    begin
        r := y;
        if (x > y) then
            r := x;
        end if;
        return r;
    end function max;

    function calc_data_width (x : INTEGER) return INTEGER is
        variable y : INTEGER;
    begin
        y := 8;
        while y < x loop
            y := y * 2;
        end loop;
        return y;
    end function calc_data_width;

    function log2 (x : INTEGER) return INTEGER is
        variable n, m : INTEGER;
    begin
        n := 0;
        m := 1;
        while m < x loop
            n := n + 1;
            m := m * 2;
        end loop;
        return n;
    end function log2;

    function cond_sel (cond : BOOLEAN; x : INTEGER; y : INTEGER) return INTEGER is
        variable ret : INTEGER;
    begin
        if (cond) then
            ret := x;
        else
            ret := y;
        end if;
        return ret;
    end function cond_sel;
    ------------------------Parameter----------------------
    constant USER_DATA_WIDTH  : INTEGER := calc_data_width(USER_DW);
    constant USER_DATA_BYTES  : INTEGER := USER_DATA_WIDTH / 8;
    constant USER_ADDR_ALIGN  : INTEGER := log2(USER_DATA_BYTES);
    constant BUS_DATA_BYTES   : INTEGER := BUS_DATA_WIDTH / 8;
    constant BUS_ADDR_ALIGN   : INTEGER := log2(BUS_DATA_BYTES);
    -- wdata buffer size 
    constant WBUFF_DEPTH      : INTEGER := cond_sel((USER_DATA_WIDTH = BUS_DATA_WIDTH),
                                                    2 * MAX_WRITE_BURST_LENGTH,
                                                    max(MAX_WRITE_BURST_LENGTH * BUS_DATA_WIDTH / USER_DATA_WIDTH, 1) ); 
    constant BURST_LEN_WIDTH  : INTEGER := cond_sel((USER_DATA_WIDTH = BUS_DATA_WIDTH),
                                                    max(log2(WBUFF_DEPTH), 8),
                                                    max(log2(MAX_WRITE_BURST_LENGTH), 8));
    constant TARGET_ADDR      : INTEGER := (C_TARGET_ADDR/USER_DATA_BYTES)*USER_DATA_BYTES;
    ------------------------Local signal-------------------
    signal next_wreq      : STD_LOGIC;
    signal ready_for_wreq : STD_LOGIC;
    signal wreq_ready     : STD_LOGIC;

    signal in_wreq_pack   : UNSIGNED(USER_AW+31 downto 0);
    signal wreq_pack      : UNSIGNED(USER_AW+31 downto 0);
    signal wreq_addr      : UNSIGNED(USER_AW-1 downto 0);
    signal wreq_len       : UNSIGNED(31 downto 0);
    signal wreq_valid     : STD_LOGIC;

    signal tmp_addr       : UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);
    signal tmp_len        : UNSIGNED(31 downto 0);
    signal tmp_valid      : STD_LOGIC;

    signal valid_length   : STD_LOGIC;
    signal next_wdata     : STD_LOGIC;
    signal wdata_valid    : STD_LOGIC;
    signal wdata_ready    : STD_LOGIC;
    signal in_wdata_pack  : UNSIGNED(USER_DW+USER_DW/8-1 downto 0);
    signal wdata_pack     : UNSIGNED(USER_DW+USER_DW/8-1 downto 0);
    signal tmp_wdata      : UNSIGNED(USER_DW-1 downto 0);
    signal tmp_wstrb      : UNSIGNED(USER_DW/8-1 downto 0);

    signal beat_pack      : UNSIGNED(BUS_DATA_WIDTH + BUS_DATA_WIDTH/8-1 downto 0);
    signal out_beat_pack  : UNSIGNED(BUS_DATA_WIDTH + BUS_DATA_WIDTH/8-1 downto 0);
    signal beat_ready     : STD_LOGIC;
    signal beat_write     : STD_LOGIC;
    signal beat_nvalid    : UNSIGNED(BURST_LEN_WIDTH downto 0);
    signal beat_nvalid_cnt: UNSIGNED(BURST_LEN_WIDTH downto 0);

    signal resp_valid     : STD_LOGIC;
    signal wrsp_ready     : STD_LOGIC;
    signal wrsp_valid     : STD_LOGIC;
    signal wrsp_read      : STD_LOGIC;
    signal wrsp_type      : UNSIGNED(0 downto 0);
    signal in_wrsp_type   : UNSIGNED(0 downto 0);

    signal ursp_ready     : STD_LOGIC;
    signal ursp_write     : STD_LOGIC;

    -- regslice io ?  no 

    component vertex_map_gmem_m_axi_fifo is
        generic (
            MEM_STYLE         : STRING  := "shiftreg";
            DATA_WIDTH        : INTEGER := 8;
            ADDR_WIDTH        : INTEGER := 4;
            DEPTH             : INTEGER := 16);
        port (
            clk               : in  STD_LOGIC;
            reset             : in  STD_LOGIC;
            clk_en            : in  STD_LOGIC;
            if_full_n         : out STD_LOGIC;
            if_write          : in  STD_LOGIC;
            if_din            : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            if_empty_n        : out STD_LOGIC;
            if_read           : in  STD_LOGIC;
            if_dout           : out UNSIGNED(DATA_WIDTH-1 downto 0);
            if_num_data_valid : out UNSIGNED(ADDR_WIDTH downto 0));
    end component vertex_map_gmem_m_axi_fifo;

    

begin
    -- Instantiation
    

    fifo_wreq : vertex_map_gmem_m_axi_fifo
    generic map (
        DATA_WIDTH        => USER_AW + 32,
        ADDR_WIDTH        => log2(USER_MAXREQS),
        DEPTH             => USER_MAXREQS)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => out_HLS_AWREADY,
        if_write          => in_HLS_AWVALID,
        if_din            => in_wreq_pack,
        if_empty_n        => wreq_valid,
        if_read           => next_wreq,
        if_dout           => wreq_pack,
        if_num_data_valid => open);

    -- ===================================================================
    -- start of AWADDR PREPROCESSOR
    in_wreq_pack    <= in_HLS_AWLEN & in_HLS_AWADDR;
    next_wreq       <= wreq_valid and ready_for_wreq and wrsp_ready;
    ready_for_wreq  <= not tmp_valid or (in_AXI_AWREADY and wreq_ready);
    wreq_len        <= wreq_pack(USER_AW + 31 downto USER_AW);
    wreq_addr       <= wreq_pack(USER_AW - 1 downto 0);

    valid_length    <= '1' when wreq_len /= 0 and wreq_len(31) = '0' else '0';
   
    out_AXI_AWID    <= TO_UNSIGNED(C_ID_VALUE, C_M_AXI_ID_WIDTH);
    out_AXI_AWLEN   <= tmp_len;   -- Byte length
    out_AXI_AWADDR  <= tmp_addr;  -- Byte address
    out_AXI_AWVALID <= tmp_valid and wreq_ready;

    process (ACLK)
    begin
        if (ACLK'event and ACLK = '1') then
            if (ARESET = '1') then
                tmp_addr <= (others => '0');
                tmp_len   <= (others => '0');
            elsif ACLK_EN = '1' then
                if (next_wreq = '1') then
                    tmp_addr  <= TARGET_ADDR + SHIFT_LEFT(RESIZE(wreq_addr, BUS_ADDR_WIDTH), USER_ADDR_ALIGN);
                    tmp_len   <= SHIFT_LEFT(wreq_len, USER_ADDR_ALIGN) - 1;
                end if;
            end if;
        end if;
    end process;

    process (ACLK)
    begin
        if (ACLK'event and ACLK = '1') then
            if (ARESET = '1') then
                tmp_valid  <= '0';
            elsif ACLK_EN = '1' then
                if (next_wreq and valid_length) = '1' then
                    tmp_valid <= '1';
                elsif (in_AXI_AWREADY and wreq_ready) = '1' then
                    tmp_valid <= '0';
                end if;
            end if;
        end if;
    end process;

    -- end of AWADDR PREPROCESSOR
    -- ===================================================================

    

    
    buff_wdata : vertex_map_gmem_m_axi_fifo
    generic map (
        MEM_STYLE         => BUFFER_IMPL,
        DATA_WIDTH        => USER_DW + USER_DW/8,
        ADDR_WIDTH        => log2(WBUFF_DEPTH),
        DEPTH             => WBUFF_DEPTH)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => wdata_ready,
        if_write          => in_HLS_WVALID,
        if_din            => in_wdata_pack,
        if_empty_n        => wdata_valid,
        if_read           => next_wdata,
        if_dout           => wdata_pack,
        if_num_data_valid => open);
    
    -- burst (beat) number data valid check
    out_AXI_BURST_REQ <= '1'         when (in_AXI_BURST_ID /= C_ID_VALUE) or (beat_nvalid > in_AXI_BURST_LEN) else '0';
    beat_nvalid_cnt   <= beat_nvalid when (in_AXI_BURST_ID /= C_ID_VALUE) or (in_AXI_BURST_ACK = '0')         else (beat_nvalid - RESIZE(in_AXI_BURST_LEN, BURST_LEN_WIDTH+1) - 1);

    
    process (ACLK)
    begin
        if (ACLK'event and ACLK = '1') then
            if (ARESET = '1') then
                beat_nvalid <= (others=>'0');
            elsif ACLK_EN = '1' then
                if (beat_ready and beat_write) = '1' then
                    beat_nvalid <= beat_nvalid_cnt + 1;
                else
                    beat_nvalid <= beat_nvalid_cnt;
                end if;
            end if;
        end if;
    end process;
    -- ===================================================================
    -- start of WDATA PREPROCESSOR
    in_wdata_pack      <= in_HLS_WSTRB & in_HLS_WDATA;
    tmp_wdata          <= wdata_pack(USER_DW-1 downto 0);
    tmp_wstrb          <= wdata_pack(USER_DW+USER_DW/8-1 downto USER_DW);
    out_HLS_WREADY     <= wdata_ready;
    out_AXI_WID        <= TO_UNSIGNED(C_ID_VALUE, C_M_AXI_ID_WIDTH);
    bus_equal_gen : if (USER_DATA_WIDTH = BUS_DATA_WIDTH) generate
    begin
        wreq_ready     <= '1';
        next_wdata     <= in_AXI_WREADY;
        out_AXI_WVALID <= wdata_valid;
        out_AXI_WDATA  <= tmp_wdata;
        out_AXI_WSTRB  <= tmp_wstrb;

        beat_ready     <= wdata_ready;
        beat_write     <= in_HLS_WVALID;
    end generate bus_equal_gen;

    bus_wide_gen : if (USER_DATA_WIDTH < BUS_DATA_WIDTH) generate
        constant TOTAL_PADS     : INTEGER := BUS_DATA_WIDTH / USER_DATA_WIDTH;
        constant PAD_ALIGN      : INTEGER := log2(TOTAL_PADS);
        constant BEAT_LEN_WIDTH : INTEGER := 32 - BUS_ADDR_ALIGN;

        function decoder (din : UNSIGNED(PAD_ALIGN-1 downto 0)) return UNSIGNED is 
            variable dout : UNSIGNED(TOTAL_PADS-1 downto 0);
        begin
            dout := (others=>'0');
            if ( not (din = 0)) then
                dout(TO_INTEGER(din)-1 downto 0) := (others=>'1');
            end if;
            return dout;
        end function decoder;

        signal  tmp_addr_end    : UNSIGNED(BUS_ADDR_WIDTH-1 downto 0);

        signal  offset_full_n   : STD_LOGIC;
        signal  offset_write    : STD_LOGIC;
        signal  start_offset    : UNSIGNED(PAD_ALIGN-1 downto 0);
        signal  end_offset      : UNSIGNED(PAD_ALIGN-1 downto 0);
        signal  beat_total      : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);
        signal  offset_info     : UNSIGNED(BEAT_LEN_WIDTH+2*PAD_ALIGN-1 downto 0);
        signal  offset_pack     : UNSIGNED(BEAT_LEN_WIDTH+2*PAD_ALIGN-1 downto 0);

        signal  offset_empty_n  : STD_LOGIC;
        signal  offset_read     : STD_LOGIC;
        signal  offset_pack_reg : UNSIGNED(BEAT_LEN_WIDTH+2*PAD_ALIGN-1 downto 0);

        signal  offset_valid    : STD_LOGIC;
        signal  next_offset     : STD_LOGIC;
        signal  head_offset     : UNSIGNED(PAD_ALIGN-1 downto 0);
        signal  tail_offset     : UNSIGNED(PAD_ALIGN-1 downto 0);

        signal  beat_len        : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);
        signal  len_cnt_buf     : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);
        signal  len_cnt_tmp     : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);

        signal  data_buf        : UNSIGNED(BUS_DATA_WIDTH-1 downto 0);
        signal  strb_buf        : UNSIGNED(BUS_DATA_BYTES-1 downto 0);
        signal  data_valid      : STD_LOGIC;

        signal  add_head        : UNSIGNED(TOTAL_PADS-1 downto 0); 
        signal  add_tail        : UNSIGNED(TOTAL_PADS-1 downto 0); 
        signal  head_pad_sel    : UNSIGNED(TOTAL_PADS-1 downto 0); 
        signal  tail_pad_sel    : UNSIGNED(0 to TOTAL_PADS-1);

        signal  pad_oh          : UNSIGNED(TOTAL_PADS - 1 downto 0);
        signal  pad_oh_reg      : UNSIGNED(TOTAL_PADS - 1 downto 0);

        signal  first_beat_set  : STD_LOGIC;
        signal  last_beat_set   : STD_LOGIC;
        signal  single_beat     : STD_LOGIC;

        signal  ready_for_data  : BOOLEAN;
        signal  first_beat      : BOOLEAN;
        signal  next_beat       : BOOLEAN;
        signal  last_beat       : BOOLEAN;
        
        signal  first_pad       : BOOLEAN;
        signal  next_pad        : BOOLEAN;
        signal  last_pad        : BOOLEAN;

    begin
        wreq_offset : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => 2*PAD_ALIGN + BEAT_LEN_WIDTH,
            ADDR_WIDTH        => log2(NUM_WRITE_OUTSTANDING),
            DEPTH             => NUM_WRITE_OUTSTANDING)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            clk_en            => ACLK_EN,
            if_full_n         => offset_full_n,
            if_write          => offset_write,
            if_din            => offset_info,
            if_empty_n        => offset_empty_n,
            if_read           => offset_read,
            if_dout           => offset_pack,
            if_num_data_valid => open);            

        buff_burst : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => BUS_DATA_WIDTH + BUS_DATA_WIDTH/8,
            ADDR_WIDTH        => log2(MAX_WRITE_BURST_LENGTH),
            DEPTH             => MAX_WRITE_BURST_LENGTH)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            clk_en            => ACLK_EN,
            if_full_n         => beat_ready,
            if_write          => beat_write,
            if_din            => beat_pack,
            if_empty_n        => out_AXI_WVALID,
            if_read           => in_AXI_WREADY,
            if_dout           => out_beat_pack,
            if_num_data_valid => open);
        
        wreq_ready       <= '1' when offset_full_n = '1' or offset_write = '0' else '0';
        tmp_addr_end     <= tmp_addr + tmp_len;
        
        offset_info      <= start_offset & end_offset & beat_total;
        start_offset     <= tmp_addr(BUS_ADDR_ALIGN-1 downto USER_ADDR_ALIGN);
        end_offset       <= not(tmp_addr_end(BUS_ADDR_ALIGN-1 downto USER_ADDR_ALIGN));
        beat_total       <= RESIZE(SHIFT_RIGHT(tmp_len + tmp_addr(BUS_ADDR_ALIGN-1 downto 0), BUS_ADDR_ALIGN), BEAT_LEN_WIDTH);

        offset_write     <= tmp_valid and in_AXI_AWREADY;
        offset_read      <= not offset_valid or next_offset;

        head_offset      <= offset_pack_reg(BEAT_LEN_WIDTH+2*PAD_ALIGN-1 downto BEAT_LEN_WIDTH+PAD_ALIGN);
        tail_offset      <= offset_pack_reg(BEAT_LEN_WIDTH+PAD_ALIGN-1 downto BEAT_LEN_WIDTH);
        beat_len         <= offset_pack_reg(BEAT_LEN_WIDTH-1 downto 0);

        beat_pack        <= strb_buf & data_buf;
        beat_write       <= data_valid;
        out_AXI_WDATA    <= out_beat_pack(BUS_DATA_WIDTH-1 downto 0);
        out_AXI_WSTRB    <= out_beat_pack(BUS_DATA_WIDTH+BUS_DATA_WIDTH/8-1 downto BUS_DATA_WIDTH);
        
        next_wdata       <= '1' when next_pad else '0';
        next_offset      <= '1' when last_beat and next_beat else '0';
        ready_for_data   <= data_valid = '0' or beat_ready = '1';

        len_cnt_tmp      <= beat_len when first_beat else len_cnt_buf;
            
        first_beat       <= first_beat_set = '1' and (offset_valid = '1');
        last_beat        <= (single_beat or last_beat_set) = '1' and (offset_valid = '1');
        next_beat        <= offset_valid = '1' and last_pad and ready_for_data;

        next_pad         <= offset_valid = '1' and wdata_valid = '1' and ready_for_data;
        last_pad         <= pad_oh(TOTAL_PADS - to_integer(tail_offset) - 1) = '1' when last_beat else
                            pad_oh(TOTAL_PADS - 1) = '1';

        head_pad_sel     <= decoder(head_offset);
        tail_pad_sel     <= decoder(tail_offset);

        pad_oh           <= (others => '0')                                                 when wdata_valid = '0' else
                            SHIFT_LEFT(TO_UNSIGNED(1, TOTAL_PADS), TO_INTEGER(head_offset)) when first_beat and first_pad else
                            TO_UNSIGNED(1, TOTAL_PADS)                                      when first_pad else
                            pad_oh_reg;

process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    single_beat <= '0';
                elsif ACLK_EN = '1' then
                    if offset_empty_n = '1' and offset_read = '1' then
                        if (offset_pack(BEAT_LEN_WIDTH-1 downto 0) = 0) then
                            single_beat <= '1';
                        else
                            single_beat <= '0';
                        end if;
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    offset_pack_reg <= (others => '0');
                elsif ACLK_EN = '1' then
                    if offset_empty_n = '1' and offset_read = '1' then
                        offset_pack_reg <= offset_pack;
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    offset_valid <= '0';
                elsif ACLK_EN = '1' then
                    if offset_empty_n = '1' and offset_read = '1' then
                        offset_valid <= '1';
                    elsif next_offset = '1' then
                        offset_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    first_beat_set <= '1';
                    last_beat_set  <= '0';
                elsif ACLK_EN = '1' then
                    if next_offset = '1' then
                        first_beat_set <= '1';
                        last_beat_set  <= '0';
                    elsif next_beat then
                        first_beat_set <= '0';
                        if len_cnt_tmp = 1 then
                            last_beat_set <= '1';
                        else
                            last_beat_set <= '0';
                        end if;
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    len_cnt_buf <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_beat then
                        len_cnt_buf <= len_cnt_tmp - 1;
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    pad_oh_reg <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_pad then
                        pad_oh_reg <= pad_oh(TOTAL_PADS - 2 downto 0) & '0';
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    first_pad <= true;
                elsif ACLK_EN = '1' then
                    if next_pad and not last_pad then
                        first_pad <= false;
                    elsif next_pad and last_pad then
                        first_pad <= true;
                    end if;
                end if;
            end if;
        end process;

        data_gen : for i in 0 to TOTAL_PADS - 1 generate
        begin
            add_head(i) <= '1' when head_pad_sel(i) = '1' and first_beat else '0';
            add_tail(i) <= '1' when tail_pad_sel(i) = '1' and last_beat else '0';

            process (ACLK)
            begin
                if (ACLK'event and ACLK = '1') then
                    if (ARESET = '1') then
                        data_buf((i+1)*USER_DATA_WIDTH - 1 downto i*USER_DATA_WIDTH) <= (others => '0'); 
                    elsif (ACLK_EN = '1') then
                        if (add_head(i) = '1' or add_tail(i) = '1') and ready_for_data then
                            data_buf((i+1)*USER_DATA_WIDTH - 1 downto i*USER_DATA_WIDTH) <= (others => '0');
                        elsif pad_oh(i) = '1' and ready_for_data then
                            data_buf((i+1)*USER_DATA_WIDTH - 1 downto i*USER_DATA_WIDTH) <= tmp_wdata;
                        end if;
                    end if;
                end if;
            end process;

            process (ACLK)
            begin
                if (ACLK'event and ACLK = '1') and ACLK_EN = '1' then
                    if (ARESET = '1') then
                        strb_buf((i+1)*USER_DATA_BYTES - 1 downto i*USER_DATA_BYTES) <= (others => '0');
                    elsif (ACLK_EN = '1') then
                        if (add_head(i) = '1' or add_tail(i) = '1') and ready_for_data then
                            strb_buf((i+1)*USER_DATA_BYTES - 1 downto i*USER_DATA_BYTES) <= (others => '0');
                        elsif pad_oh(i) = '1' and ready_for_data then
                            strb_buf((i+1)*USER_DATA_BYTES - 1 downto i*USER_DATA_BYTES) <= tmp_wstrb;
                        end if;
                    end if;
                end if;
            end process;
        end generate data_gen;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_valid <= '0';
                elsif ACLK_EN = '1' then
                    if next_beat then
                        data_valid <= '1';
                    elsif ready_for_data then
                        data_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

    end generate bus_wide_gen; 

    bus_narrow_gen : if (USER_DATA_WIDTH > BUS_DATA_WIDTH) generate
        constant TOTAL_SPLIT    : INTEGER := USER_DATA_WIDTH / BUS_DATA_WIDTH;
        constant SPLIT_ALIGN    : INTEGER := log2(TOTAL_SPLIT);
        constant BEAT_LEN_WIDTH : INTEGER := 32 - BUS_ADDR_ALIGN;

        
        signal  tmp_addr_end    : UNSIGNED(BUS_ADDR_WIDTH-1 downto 0); 
        signal  offset_full_n   : STD_LOGIC;
        signal  offset_write    : STD_LOGIC;
        signal  beat_total      : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);

        signal  offset_valid    : STD_LOGIC;
        signal  next_offset     : STD_LOGIC;
        signal  beat_len        : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);
        signal  len_cnt         : UNSIGNED(BEAT_LEN_WIDTH-1 downto 0);

        signal  data_buf        : UNSIGNED(USER_DATA_WIDTH - 1 downto 0);
        signal  strb_buf        : UNSIGNED(USER_DATA_BYTES - 1 downto 0);
        signal  data_valid      : STD_LOGIC;
        signal  split_cnt       : UNSIGNED(SPLIT_ALIGN - 1 downto 0);
        signal  first_split     : BOOLEAN;
        signal  next_split      : BOOLEAN;
        signal  last_split      : BOOLEAN;
        signal  ready_for_data  : BOOLEAN;
    begin
        -- instantiation
        wreq_offset : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => BEAT_LEN_WIDTH,
            ADDR_WIDTH        => log2(NUM_WRITE_OUTSTANDING),
            DEPTH             => NUM_WRITE_OUTSTANDING)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            clk_en            => ACLK_EN,
            if_full_n         => offset_full_n,
            if_write          => offset_write,
            if_din            => beat_total,
            if_empty_n        => offset_valid,
            if_read           => next_offset,
            if_dout           => beat_len,
            if_num_data_valid => open);

        buff_burst : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => BUS_DATA_WIDTH + BUS_DATA_WIDTH/8,
            ADDR_WIDTH        => log2(MAX_WRITE_BURST_LENGTH),
            DEPTH             => MAX_WRITE_BURST_LENGTH)
        port map (
            clk               => ACLK,
            reset             => ARESET,
            clk_en            => ACLK_EN,
            if_full_n         => beat_ready,
            if_write          => beat_write,
            if_din            => beat_pack,
            if_empty_n        => out_AXI_WVALID,
            if_read           => in_AXI_WREADY,
            if_dout           => out_beat_pack,
            if_num_data_valid => open);

        wreq_ready       <= offset_full_n and not offset_write;
        tmp_addr_end     <= tmp_addr + tmp_len;
        beat_total       <= RESIZE(SHIFT_RIGHT(tmp_len + tmp_addr(BUS_ADDR_ALIGN-1 downto 0), BUS_ADDR_ALIGN), BEAT_LEN_WIDTH);
        offset_write     <= tmp_valid and in_AXI_AWREADY;

        beat_pack        <= strb_buf & data_buf;
        beat_write       <= data_valid;
        out_AXI_WDATA    <= out_beat_pack(BUS_DATA_WIDTH-1 downto 0);
        out_AXI_WSTRB    <= out_beat_pack(BUS_DATA_WIDTH+BUS_DATA_WIDTH/8-1 downto BUS_DATA_WIDTH);

        next_wdata       <= '1' when first_split else '0';
        next_offset      <= '1' when len_cnt = beat_len and offset_valid = '1' and last_split else '0';
        ready_for_data   <= data_valid = '0' or beat_ready = '1';

        first_split      <= split_cnt = 0  and wdata_valid = '1' and offset_valid ='1' and ready_for_data;
        next_split       <= split_cnt /= 0 and ready_for_data;
        last_split       <= split_cnt = (TOTAL_SPLIT - 1) and ready_for_data;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    split_cnt <= (others => '0');
                elsif ACLK_EN = '1' then
                    if last_split then
                        split_cnt <= (others => '0');
                    elsif first_split or next_split then
                        split_cnt <= split_cnt + 1;
                    end if;
                end if;
            end if;
        end process ;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    len_cnt <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_offset = '1' then
                        len_cnt <= (others => '0');
                    elsif next_wdata = '1' or next_split then
                        len_cnt <= len_cnt + 1;
                    end if;
                end if;
            end if;
        end process ;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_buf <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_wdata = '1' then
                        data_buf <= tmp_wdata;
                    elsif next_split then
                        data_buf <= SHIFT_RIGHT(data_buf, BUS_DATA_WIDTH);
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    strb_buf <= (others => '0');
                elsif ACLK_EN = '1' then
                    if next_wdata = '1' then
                        strb_buf <= tmp_wstrb;
                    elsif next_split then
                        strb_buf <= SHIFT_RIGHT(strb_buf, BUS_DATA_BYTES);
                    end if;
                end if;
            end if;
        end process;

        process (ACLK)
        begin
            if (ACLK'event and ACLK = '1') then
                if (ARESET = '1') then
                    data_valid <= '0';
                elsif ACLK_EN = '1' then
                    if next_wdata = '1' then
                        data_valid <= '1';
                    elsif not (first_split or next_split) and ready_for_data then
                        data_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

    end generate bus_narrow_gen;

    -- ===================================================================
    -- generate response for all request (including request with invalid length)
    fifo_wrsp : vertex_map_gmem_m_axi_fifo
    generic map (
        DATA_WIDTH        => 1,
        ADDR_WIDTH        => log2(NUM_WRITE_OUTSTANDING),
        DEPTH             => NUM_WRITE_OUTSTANDING)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => wrsp_ready,
        if_write          => next_wreq,
        if_din            => in_wrsp_type,
        if_empty_n        => wrsp_valid,
        if_read           => wrsp_read,
        if_dout           => wrsp_type,  -- "1" for valid length request, "0" for invalid length request
        if_num_data_valid => open);
    
    user_resp : vertex_map_gmem_m_axi_fifo
    generic map (
        DATA_WIDTH        => 1,
        ADDR_WIDTH        => log2(USER_MAXREQS),
        DEPTH             => USER_MAXREQS)
    port map (
        clk               => ACLK,
        reset             => ARESET,
        clk_en            => ACLK_EN,
        if_full_n         => ursp_ready,
        if_write          => ursp_write,
        if_din            => "0",
        if_empty_n        => out_HLS_BVALID,
        if_read           => in_HLS_BREADY,
        if_dout           => open,
        if_num_data_valid => open);

    

    resp_valid <= '1' when (in_AXI_BVALID = '1') and (in_AXI_BID = C_ID_VALUE) else '0';
    out_AXI_BREADY <= wrsp_type(0) and ursp_ready;

    in_wrsp_type   <= "1" when valid_length = '1' else "0";
    ursp_write     <= wrsp_valid and (not wrsp_type(0) or resp_valid);
    wrsp_read      <= ursp_ready and ursp_write;

end architecture behave;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_arbiter is
    generic(
        STRATEGY      : STRING := "load_balance";
        PORTS_WIDTH   : INTEGER := 2;
        PORTS         : INTEGER := 4);
    port (
        clk           : in  STD_LOGIC;
        reset         : in  STD_LOGIC;
        s_ready       : in  UNSIGNED(PORTS-1 downto 0);
        s_valid       : out STD_LOGIC;
        s_index       : out UNSIGNED(PORTS_WIDTH-1 downto 0);
        m_valid       : in  UNSIGNED(PORTS-1 downto 0);
        m_ready       : out UNSIGNED(PORTS-1 downto 0));
end entity vertex_map_gmem_m_axi_arbiter;

architecture behave of vertex_map_gmem_m_axi_arbiter is
    function or_reduce(a : UNSIGNED(PORTS-1 downto 0)) return STD_LOGIC is
        variable ret : STD_LOGIC := '0';
    begin
        for i in a'range loop
            ret := ret or a(i);
        end loop;
    
        return ret;
    end function or_reduce;

    function arbiter_grant(req  : UNSIGNED(PORTS-1 downto 0);
                           base : UNSIGNED(PORTS-1 downto 0)) return UNSIGNED is
        variable req_buff : UNSIGNED(2*PORTS-1 downto 0);
        variable gnt_buff : UNSIGNED(2*PORTS-1 downto 0);
        variable gnt : UNSIGNED(PORTS-1 downto 0);
    begin
        req_buff := req & req;
        gnt_buff := req_buff AND (not(req_buff - base));
        gnt := gnt_buff(2*PORTS-1 downto PORTS) OR gnt_buff(PORTS-1 downto 0);

        return gnt;
    end function arbiter_grant;

    function onehot_bin2dec(bin : UNSIGNED(PORTS-1 downto 0)) return UNSIGNED is
        variable mask : UNSIGNED(PORTS-1 downto 0);
        variable dec  : UNSIGNED(PORTS_WIDTH-1 downto 0);
        variable tmp  : UNSIGNED(PORTS_WIDTH-1 downto 0);
    begin
        for i in 0 to PORTS_WIDTH-1 loop
            for j in 0 to PORTS-1 loop
                tmp    := TO_UNSIGNED(j, PORTS_WIDTH);
                mask(j) := tmp(i);
            end loop;
            dec(i) := or_reduce(bin and mask);
        end loop;
    
        return dec;
    end function onehot_bin2dec;

    signal base  : UNSIGNED(PORTS-1 downto 0) := TO_UNSIGNED(1, PORTS);
    signal req   : UNSIGNED(PORTS-1 downto 0);
    signal gnt   : UNSIGNED(PORTS-1 downto 0);
begin
    m_ready  <= gnt;
    s_valid  <= or_reduce(gnt);

    req      <= m_valid AND s_ready;
    s_index  <= onehot_bin2dec(gnt);

    process ( clk )
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                base <= TO_UNSIGNED(1, PORTS);
            elsif (or_reduce(gnt) = '1') then
                base <= gnt(PORTS-2 downto 0) & gnt(PORTS-1);
            end if;
        end if;
    end process;

    round_robin_gen : if (STRATEGY = "round_robin") generate
        gnt <= req AND base;
    end generate round_robin_gen;

    load_balance_gen : if (STRATEGY /= "round_robin") generate
        gnt <= arbiter_grant(req, base);
    end generate load_balance_gen;

end architecture behave;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_crossbar is
    generic(
        PORTS_WIDTH   : INTEGER := 2;
        PORTS         : INTEGER := 4);
    port (
        s_ready       : in  STD_LOGIC;
        s_valid       : out STD_LOGIC;
        s_index       : in  UNSIGNED(PORTS_WIDTH-1 downto 0);
        m_valid       : in  UNSIGNED(PORTS-1 downto 0);
        m_ready       : out UNSIGNED(PORTS-1 downto 0));
end entity vertex_map_gmem_m_axi_crossbar;

architecture behave of vertex_map_gmem_m_axi_crossbar is
begin

    s_valid <= m_valid(TO_INTEGER(s_index));
    m_ready <= SHIFT_LEFT( TO_UNSIGNED(1, PORTS), TO_INTEGER(s_index)) when s_ready = '1' else (others=>'0');

end architecture behave;


