library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_burst_interleave is
    generic (
        ID_WIDTH          : INTEGER := 1;
        DATA_WIDTH        : INTEGER := 32;
        ADDR_WIDTH        : INTEGER := 32;
        MAX_BURST_LENGTH  : INTEGER := 16;
        NUM_PORTS         : INTEGER := 1);
    port (
        clk               : in  STD_LOGIC;
        reset             : in  STD_LOGIC;
        clk_en            : in  STD_LOGIC;

        in_REQ_ID         : in  UNSIGNED(ID_WIDTH-1 downto 0);
        in_REQ_ADDR       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        in_REQ_LEN        : in  UNSIGNED(31 downto 0);
        in_REQ_VALID      : in  STD_LOGIC;
        out_REQ_READY     : out UNSIGNED(NUM_PORTS-1 downto 0);

        out_BURST_ID      : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_BURST_ADDR    : out UNSIGNED(ADDR_WIDTH-1 downto 0);
        out_BURST_LEN     : out UNSIGNED(7 downto 0);
        out_BURST_VALID   : out STD_LOGIC;
        in_BURST_READY    : in  STD_LOGIC;

        out_CTRL_ID       : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_CTRL_INFO     : out UNSIGNED(0 downto 0);
        out_CTRL_LEN      : out UNSIGNED(7 downto 0);
        out_CTRL_VALID    : out STD_LOGIC;
        in_CTRL_READY     : in  UNSIGNED(NUM_PORTS-1 downto 0));

end entity vertex_map_gmem_m_axi_burst_interleave;

architecture behave of vertex_map_gmem_m_axi_burst_interleave is

    function or_reduce(a : UNSIGNED(NUM_PORTS-1 downto 0)) return STD_LOGIC is
        variable ret : STD_LOGIC := '0';
    begin
        for i in a'range loop
            ret := ret or a(i);
        end loop;
    
        return ret;
    end function or_reduce;

    function log2 (x : INTEGER) return INTEGER is
        variable n, m : INTEGER;
    begin
        n := 0;
        m := 1;
        while m < x loop
            n := n + 1;
            m := m * 2;
        end loop;
        return n;
    end function log2;

    --common
    constant PACK_WIDTH           : INTEGER := ID_WIDTH + ADDR_WIDTH + 32;
    constant DATA_BYTES           : INTEGER := DATA_WIDTH / 8;
    constant ADDR_ALIGN           : INTEGER := log2(DATA_BYTES);
    constant BOUNDARY_BEATS       : UNSIGNED(11-ADDR_ALIGN downto 0) := (others => '1');
    constant NUM_BEAT_WIDTH       : INTEGER := log2(MAX_BURST_LENGTH);

    --local signals
    signal  req_pack_in           : UNSIGNED(PACK_WIDTH-1 downto 0);
    signal  req_pack_out          : UNSIGNED(PACK_WIDTH-1 downto 0);
    signal  req_id_tmp            : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  req_addr_tmp          : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  req_len_tmp           : UNSIGNED(31 downto 0);
    signal  req_ready             : UNSIGNED(NUM_PORTS-1 downto 0);
    
    signal  req_full_n            : STD_LOGIC;
    signal  req_empty_n           : STD_LOGIC;
    signal  write_req             : STD_LOGIC;
    signal  read_req              : STD_LOGIC;
    signal  next_req              : STD_LOGIC;

    signal  start_addr            : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  end_addr              : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  sect_addr             : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  sect_addr_buf         : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  req_id                : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  req_id_buf            : UNSIGNED(ID_WIDTH-1 downto 0);

    signal  beat_len              : UNSIGNED(31 downto 0);
    signal  beat_len_buf          : UNSIGNED(31 downto 0);
    signal  start_to_4k           : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_len              : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_len_buf          : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_cnt              : UNSIGNED(ADDR_WIDTH-13 downto 0);

    signal  req_handling          : BOOLEAN;
    signal  first_sect            : BOOLEAN;
    signal  last_sect             : BOOLEAN;
    signal  last_sect_buf         : BOOLEAN;
    signal  ready_for_sect        : BOOLEAN;
    signal  next_sect             : BOOLEAN;

    signal  burst_valid           : STD_LOGIC;

    signal  ost_ctrl_id           : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  ost_ctrl_info         : UNSIGNED(0 downto 0);
    signal  ost_ctrl_len          : UNSIGNED(7 downto 0);
    signal  ost_ctrl_valid        : STD_LOGIC;
    signal  ost_ctrl_ready        : STD_LOGIC;

    signal  rem_req_pack          : UNSIGNED(PACK_WIDTH-1 downto 0);
    signal  rem_req_valid         : STD_LOGIC;
    signal  rem_req_id            : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  rem_req_addr          : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  rem_req_len           : UNSIGNED(31 downto 0);

    component vertex_map_gmem_m_axi_fifo is
        generic (
            MEM_STYLE         : STRING  := "shiftreg";
            DATA_WIDTH        : INTEGER := 8;
            ADDR_WIDTH        : INTEGER := 4;
            DEPTH             : INTEGER := 16);
        port (
            clk               : in  STD_LOGIC;
            reset             : in  STD_LOGIC;
            clk_en            : in  STD_LOGIC;
            if_full_n         : out STD_LOGIC;
            if_write          : in  STD_LOGIC;
            if_din            : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            if_empty_n        : out STD_LOGIC;
            if_read           : in  STD_LOGIC;
            if_dout           : out UNSIGNED(DATA_WIDTH-1 downto 0);
            if_num_data_valid : out UNSIGNED(ADDR_WIDTH downto 0));
    end component vertex_map_gmem_m_axi_fifo;

    component vertex_map_gmem_m_axi_reg_slice is
        generic (
            DATA_WIDTH  : INTEGER := 8);
        port (
            clk         : in  STD_LOGIC;
            reset       : in  STD_LOGIC;
            s_data      : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            s_valid     : in  STD_LOGIC;
            s_ready     : out STD_LOGIC;
            m_data      : out UNSIGNED(DATA_WIDTH-1 downto 0);
            m_valid     : out STD_LOGIC;
            m_ready     : in  STD_LOGIC);
    end component vertex_map_gmem_m_axi_reg_slice;

begin
    --------------------------- AR channel begin -----------------------------------
    -- Instantiation
    num_ports_gt2 : if (NUM_PORTS > 2) generate 
        req_buffer : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH => PACK_WIDTH,
            DEPTH      => NUM_PORTS,
            ADDR_WIDTH => log2(NUM_PORTS))
        port map (
            clk        => clk,
            reset      => reset,
            clk_en     => clk_en,
            if_full_n  => req_full_n,
            if_write   => write_req,
            if_din     => req_pack_in,
            if_empty_n => req_empty_n,
            if_read    => read_req,
            if_dout    => req_pack_out,
            if_num_data_valid => open);
    end generate num_ports_gt2;
    
    num_ports_ngt2 : if (NUM_PORTS <= 2) generate 
        rs_req : vertex_map_gmem_m_axi_reg_slice
        generic map (
            DATA_WIDTH =>  PACK_WIDTH)
        port map (
            clk        =>  clk,
            reset      =>  reset,
            s_data     =>  req_pack_in,
            s_valid    =>  write_req,
            s_ready    =>  req_full_n,
            m_data     =>  req_pack_out,
            m_valid    =>  req_empty_n,
            m_ready    =>  read_req);
    end generate num_ports_ngt2;

    out_REQ_READY      <= req_ready    when req_full_n = '1' and rem_req_valid = '0'   else (others=>'0');
    req_pack_in        <= rem_req_pack when rem_req_valid = '1' else (in_REQ_ID & in_REQ_LEN & in_REQ_ADDR);
    write_req          <= rem_req_valid or in_REQ_VALID;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_ready <= (others=>'1');
            elsif clk_en = '1' then
                if in_REQ_VALID = '1' and req_full_n = '1' and rem_req_valid = '0' then
                    req_ready(TO_INTEGER(in_REQ_ID)) <= '0';
                end if;
                if ost_ctrl_info = "1" and ost_ctrl_valid = '1' then
                    req_ready(TO_INTEGER(ost_ctrl_id)) <= '1';
                end if;
            end if;
        end if;
    end process;    

    req_addr_tmp       <= req_pack_out(ADDR_WIDTH-1  downto 0);
    req_len_tmp        <= req_pack_out(ADDR_WIDTH+31 downto ADDR_WIDTH);
    req_id_tmp         <= req_pack_out(PACK_WIDTH-1  downto ADDR_WIDTH+32);
 
    next_req           <= read_req and req_empty_n;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_id      <= (others => '0');
                start_addr  <= (others => '0');
                end_addr    <= (others => '0');
                start_to_4k <= (others => '0');
            elsif clk_en = '1' then
                if next_req = '1' then
                    req_id      <= req_id_tmp;
                    start_addr  <= req_addr_tmp(ADDR_WIDTH-1 downto ADDR_ALIGN) & (ADDR_ALIGN-1 downto 0 => '0');
                    end_addr    <= req_addr_tmp + req_len_tmp;
                    start_to_4k <= BOUNDARY_BEATS - req_addr_tmp(11 downto ADDR_ALIGN);
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_handling <= false;
            elsif clk_en = '1' then
                if next_req = '1' then
                    req_handling <= true;
                elsif req_empty_n = '0' and last_sect and next_sect then
                    req_handling <= false;
                end if;
            end if;
        end if;
    end process;
        
    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                sect_cnt <= (others => '0');
                beat_len <= (others => '0');
            elsif clk_en = '1' then
                if next_req = '1' then
                    sect_cnt <= req_addr_tmp(ADDR_WIDTH - 1 downto 12);
                    beat_len <= SHIFT_RIGHT(req_len_tmp + req_addr_tmp(ADDR_ALIGN-1 downto 0), ADDR_ALIGN);
                elsif next_sect then
                    sect_cnt <= sect_cnt + 1;
                    beat_len <= beat_len - sect_len - 1;
                end if;
            end if;
        end if;
    end process;

    first_sect <= (sect_cnt = start_addr(ADDR_WIDTH - 1 downto 12));
    last_sect  <= (sect_cnt = end_addr(ADDR_WIDTH -1 downto 12));

    sect_addr  <= start_addr when first_sect else
                  sect_cnt & (11 downto 0 => '0');
    sect_len   <= beat_len(11-ADDR_ALIGN downto 0) when     first_sect and     last_sect else
                  start_to_4k                      when     first_sect and not last_sect else
                  end_addr(11 downto ADDR_ALIGN)   when not first_sect and     last_sect else
                  BOUNDARY_BEATS;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_id_buf    <= (others => '0');
                sect_addr_buf <= (others => '0');
                sect_len_buf  <= (others => '0');
                last_sect_buf <= false;
                beat_len_buf  <= (others => '0');
            elsif clk_en = '1' then
                if next_sect then
                    req_id_buf    <= req_id;
                    sect_addr_buf <= sect_addr;
                    sect_len_buf  <= sect_len;
                    last_sect_buf <= last_sect;
                    beat_len_buf  <= beat_len;
                end if;
            end if;
        end if;
    end process; 

    out_CTRL_VALID      <= ost_ctrl_valid;
    out_CTRL_ID         <= ost_ctrl_id;
    out_CTRL_INFO       <= ost_ctrl_info;
    out_CTRL_LEN        <= ost_ctrl_len;

    must_one_burst : if (DATA_BYTES >= 4096/MAX_BURST_LENGTH) generate
        signal  read_sect    : BOOLEAN;
    begin
        out_BURST_ID    <= req_id_buf;
        out_BURST_ADDR  <= sect_addr_buf;
        out_BURST_LEN   <= RESIZE(sect_len_buf, 8);
        out_BURST_VALID <= burst_valid;

        ost_ctrl_id     <= req_id;
        ost_ctrl_len    <= RESIZE(sect_len, 8);
        ost_ctrl_info   <= "1" when last_sect else "0";
        ost_ctrl_valid  <= '1' when next_sect else '0';
        ost_ctrl_ready  <= in_CTRL_READY(TO_INTEGER(req_id));

        next_sect       <= read_sect and ost_ctrl_ready = '1';
        ready_for_sect  <= not (burst_valid = '1' and in_BURST_READY = '0') and req_full_n = '1' and or_reduce(in_CTRL_READY) = '1';
        read_sect       <= req_handling and ready_for_sect;
        read_req        <= '1' when not req_handling or ready_for_sect else '0';

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    burst_valid <= '0';
                elsif clk_en = '1' then
                    if next_sect then
                        burst_valid <= '1';
                    elsif in_BURST_READY = '1' then
                        burst_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        -- calculate remaining request, for interleaved burst handling.
        rem_req_pack  <= rem_req_id & (rem_req_len(31-ADDR_ALIGN downto 0) & (ADDR_ALIGN-1 downto 0 => '1')) & rem_req_addr;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    rem_req_id   <= (others => '0'); 
                    rem_req_addr <= (others => '0');
                    rem_req_len  <= (others => '0');
                elsif clk_en = '1' then
                    if next_sect then
                        rem_req_id   <= req_id;
                        rem_req_addr <= (sect_cnt+1) & (11 downto 0 => '0');
                        rem_req_len <= beat_len - sect_len - 1;
                    elsif read_sect then
                        rem_req_id   <= req_id;
                        rem_req_addr <= sect_addr;
                        rem_req_len  <= beat_len;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    rem_req_valid <= '0';
                elsif clk_en = '1' then
                    if next_sect and last_sect then
                        rem_req_valid <= '0';
                    elsif req_empty_n = '1' and read_sect then
                        rem_req_valid <= '1';
                    elsif req_full_n = '1' then
                        rem_req_valid <= '0';
                    end if;
                end if;
            end if;
        end process;
    end generate must_one_burst;

    could_multi_bursts : if (DATA_BYTES < 4096/MAX_BURST_LENGTH) generate
        signal  addr_tmp        : UNSIGNED(ADDR_WIDTH - 1 downto 0);
        signal  addr_buf        : UNSIGNED(ADDR_WIDTH - 1 downto 0);
        signal  len_tmp         : UNSIGNED(7 downto 0);
        signal  len_buf         : UNSIGNED(7 downto 0);
        signal  id_buf          : UNSIGNED(ID_WIDTH-1 downto 0); 
        signal  rem_len_tmp     : UNSIGNED(31 downto 0);
        signal  loop_cnt        : UNSIGNED(11 - NUM_BEAT_WIDTH - ADDR_ALIGN downto 0);
        signal  first_loop      : BOOLEAN;
        signal  last_loop       : BOOLEAN;
        signal  next_loop       : BOOLEAN;
        signal  read_loop       : BOOLEAN;
        signal  ready_for_loop  : BOOLEAN;
        signal  sect_handling   : BOOLEAN;
        signal  next_req_ready  : BOOLEAN;

        signal  last_loop_when_next_loop : BOOLEAN;
        signal  last_loop_when_next_sect : BOOLEAN;
        signal  len_tmp_when_next_loop   : UNSIGNED(7 downto 0); 
        signal  len_tmp_when_next_sect   : UNSIGNED(7 downto 0); 
    begin
        out_BURST_ID    <= id_buf;
        out_BURST_ADDR  <= addr_buf;
        out_BURST_LEN   <= len_buf;
        out_BURST_VALID <= burst_valid;

        ost_ctrl_id     <= req_id_buf;
        ost_ctrl_len    <= len_tmp;
        ost_ctrl_info   <= "1" when last_sect_buf and last_loop else "0";
        ost_ctrl_valid  <= '1' when next_loop else '0';
        ost_ctrl_ready  <= in_CTRL_READY(TO_INTEGER(req_id_buf));
        
        read_req        <= '1' when not next_req_ready or ready_for_sect else '0';

        next_sect       <= req_handling and ready_for_sect;
        ready_for_sect  <= not sect_handling or (read_loop and next_req_ready) or (next_loop and last_loop);
        
        next_loop       <= read_loop and ost_ctrl_ready = '1';
        read_loop       <= sect_handling and ready_for_loop;
        ready_for_loop  <= not (burst_valid = '1' and in_BURST_READY = '0') and req_full_n = '1' and or_reduce(in_CTRL_READY) = '1'; 

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    burst_valid <= '0';
                elsif clk_en = '1' then
                    if next_loop then
                        burst_valid <= '1';
                    elsif in_BURST_READY = '1' then
                        burst_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    sect_handling <= false;
                elsif clk_en = '1' then
                    if req_handling and not sect_handling then
                        sect_handling <= true;
                    elsif not req_handling and last_loop and next_loop then
                        sect_handling <= false;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    loop_cnt   <= (others => '0');
                    first_loop <= true;
                    last_loop  <= true;
                elsif clk_en = '1' then
                    if next_sect then
                        loop_cnt   <= (others => '0');
                        first_loop <= true;
                        last_loop  <= last_loop_when_next_sect;
                    elsif next_loop then
                        loop_cnt   <= loop_cnt + 1;
                        first_loop <= false;
                        last_loop  <= last_loop_when_next_loop;
                    end if;
                end if;
            end if;
        end process;

        last_loop_when_next_sect <= (sect_len(11 - ADDR_ALIGN downto NUM_BEAT_WIDTH) = 0);
        last_loop_when_next_loop <= (sect_len_buf(11 - ADDR_ALIGN downto NUM_BEAT_WIDTH) = (loop_cnt+1));

        len_tmp_when_next_sect <= RESIZE(sect_len(NUM_BEAT_WIDTH-1 downto 0), 8)     when last_loop_when_next_sect else TO_UNSIGNED(2**NUM_BEAT_WIDTH-1, 8);
        len_tmp_when_next_loop <= RESIZE(sect_len_buf(NUM_BEAT_WIDTH-1 downto 0), 8) when last_loop_when_next_loop else TO_UNSIGNED(2**NUM_BEAT_WIDTH-1, 8);

        addr_tmp     <= sect_addr_buf when first_loop else (addr_buf + SHIFT_LEFT(RESIZE(len_buf, 32) + 1, ADDR_ALIGN));
        rem_len_tmp  <= beat_len_buf  when first_loop else rem_req_len;
        rem_req_pack <= rem_req_id & (rem_req_len(31-ADDR_ALIGN downto 0) & (ADDR_ALIGN-1 downto 0 => '1')) & rem_req_addr; 

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    len_tmp <= TO_UNSIGNED(2**NUM_BEAT_WIDTH-1, 8);
                elsif clk_en = '1' then
                    if next_sect then
                        len_tmp <= len_tmp_when_next_sect;
                    elsif next_loop then
                        len_tmp <= len_tmp_when_next_loop;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    addr_buf <= (others => '0');
                    len_buf  <= (others => '0');
                    id_buf   <= (others => '0');
                elsif clk_en = '1' then
                    if next_loop then
                        addr_buf <= addr_tmp;
                        len_buf  <= len_tmp;
                        id_buf   <= req_id_buf;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    rem_req_id   <= (others => '0');
                    rem_req_addr <= (others => '0');
                    rem_req_len  <= (others => '0');
                elsif clk_en = '1' then
                    if next_loop then
                        rem_req_id   <= req_id_buf;
                        rem_req_addr <= addr_tmp + SHIFT_LEFT(RESIZE(len_tmp, 32) + 1, ADDR_ALIGN);
                        rem_req_len  <= rem_len_tmp - len_tmp - 1;
                    elsif read_loop then
                        rem_req_id   <= req_id_buf;
                        rem_req_addr <= addr_tmp;
                        rem_req_len  <= rem_len_tmp;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    next_req_ready   <= false;
                elsif clk_en = '1' then
                    if next_req = '1' then
                        next_req_ready   <= true;
                    elsif next_sect then
                        next_req_ready   <= false;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    rem_req_valid <= '0';
                elsif clk_en = '1' then
                    if next_loop and last_loop and last_sect_buf then
                        rem_req_valid <= '0';
                    elsif next_req_ready and read_loop then
                        rem_req_valid <= '1';
                    elsif req_full_n = '1' then
                        rem_req_valid <= '0';
                    end if;
                end if;
            end if;
        end process; 
    end generate could_multi_bursts;
end architecture behave;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_burst_sequential is
    generic (
        ID_WIDTH          : INTEGER := 1;
        DATA_WIDTH        : INTEGER := 32;
        ADDR_WIDTH        : INTEGER := 32;
        MAX_BURST_LENGTH  : INTEGER := 16;
        NUM_PORTS         : INTEGER := 1);
    port (
        clk               : in  STD_LOGIC;
        reset             : in  STD_LOGIC;
        clk_en            : in  STD_LOGIC;

        in_REQ_ID         : in  UNSIGNED(ID_WIDTH-1 downto 0);
        in_REQ_ADDR       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        in_REQ_LEN        : in  UNSIGNED(31 downto 0);
        in_REQ_VALID      : in  STD_LOGIC;
        out_REQ_READY     : out UNSIGNED(NUM_PORTS-1 downto 0);

        out_BURST_ID      : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_BURST_ADDR    : out UNSIGNED(ADDR_WIDTH-1 downto 0);
        out_BURST_LEN     : out UNSIGNED(7 downto 0);
        out_BURST_VALID   : out STD_LOGIC;
        in_BURST_READY    : in  STD_LOGIC;

        out_CTRL_ID       : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_CTRL_INFO     : out UNSIGNED(0 downto 0);
        out_CTRL_LEN      : out UNSIGNED(7 downto 0);
        out_CTRL_VALID    : out STD_LOGIC;
        in_CTRL_READY     : in  UNSIGNED(NUM_PORTS-1 downto 0));

end entity vertex_map_gmem_m_axi_burst_sequential;

architecture behave of vertex_map_gmem_m_axi_burst_sequential is

    function log2 (x : INTEGER) return INTEGER is
        variable n, m : INTEGER;
    begin
        n := 0;
        m := 1;
        while m < x loop
            n := n + 1;
            m := m * 2;
        end loop;
        return n;
    end function log2;

    --common
    constant PACK_WIDTH           : INTEGER := ID_WIDTH + ADDR_WIDTH + 32;
    constant DATA_BYTES           : INTEGER := DATA_WIDTH / 8;
    constant ADDR_ALIGN           : INTEGER := log2(DATA_BYTES);
    constant BOUNDARY_BEATS       : UNSIGNED(11-ADDR_ALIGN downto 0) := (others => '1');
    constant NUM_BEAT_WIDTH       : INTEGER := log2(MAX_BURST_LENGTH);

    --local signals
    signal  req_pack_in           : UNSIGNED(PACK_WIDTH-1 downto 0);
    signal  req_pack_out          : UNSIGNED(PACK_WIDTH-1 downto 0);
    signal  req_id_tmp            : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  req_addr_tmp          : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  req_len_tmp           : UNSIGNED(31 downto 0);
    
    signal  req_full_n            : STD_LOGIC;
    signal  req_empty_n           : STD_LOGIC;
    signal  write_req             : STD_LOGIC;
    signal  read_req              : STD_LOGIC;
    signal  next_req              : STD_LOGIC;

    signal  start_addr            : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  sect_addr             : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  sect_addr_buf         : UNSIGNED(ADDR_WIDTH-1 downto 0);
    signal  req_id                : UNSIGNED(ID_WIDTH-1 downto 0);
    signal  req_id_buf            : UNSIGNED(ID_WIDTH-1 downto 0);

    signal  beat_len              : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  start_to_4k           : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  end_from_4k           : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_len              : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_len_buf          : UNSIGNED(11-ADDR_ALIGN downto 0);
    signal  sect_cnt              : UNSIGNED(ADDR_WIDTH-13 downto 0);
    signal  sect_total            : UNSIGNED(19 downto 0);
    signal  sect_total_buf        : UNSIGNED(19 downto 0);
    signal  sect_total_tmp        : UNSIGNED(19 downto 0);

    signal  req_handling          : BOOLEAN;
    signal  single_sect           : BOOLEAN;
    signal  first_sect            : BOOLEAN;
    signal  last_sect             : BOOLEAN;
    signal  last_sect_buf         : BOOLEAN;
    signal  last_sect_tmp         : BOOLEAN;
    signal  ready_for_sect        : BOOLEAN;
    signal  next_sect             : BOOLEAN;

    signal  burst_valid           : STD_LOGIC;

    component vertex_map_gmem_m_axi_reg_slice is
        generic (
            DATA_WIDTH  : INTEGER := 8);
        port (
            clk         : in  STD_LOGIC;
            reset       : in  STD_LOGIC;
            s_data      : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            s_valid     : in  STD_LOGIC;
            s_ready     : out STD_LOGIC;
            m_data      : out UNSIGNED(DATA_WIDTH-1 downto 0);
            m_valid     : out STD_LOGIC;
            m_ready     : in  STD_LOGIC);
    end component vertex_map_gmem_m_axi_reg_slice;

begin
    --------------------------- AR channel begin -----------------------------------
    -- Instantiation
    rs_req : vertex_map_gmem_m_axi_reg_slice
        generic map (
            DATA_WIDTH =>  PACK_WIDTH)
        port map (
            clk        =>  clk,
            reset      =>  reset,
            s_data     =>  req_pack_in,
            s_valid    =>  write_req,
            s_ready    =>  req_full_n,
            m_data     =>  req_pack_out,
            m_valid    =>  req_empty_n,
            m_ready    =>  read_req);

    out_REQ_READY      <= (others=>'1') when req_full_n = '1' else (others=>'0');
    req_pack_in        <= in_REQ_ID & in_REQ_LEN & in_REQ_ADDR;
    write_req          <= in_REQ_VALID;

    req_addr_tmp       <= req_pack_out(ADDR_WIDTH-1  downto 0);
    req_len_tmp        <= req_pack_out(ADDR_WIDTH+31 downto ADDR_WIDTH);
    req_id_tmp         <= req_pack_out(PACK_WIDTH-1  downto ADDR_WIDTH+32);

    read_req           <= '1' when not req_handling or (last_sect_tmp and next_sect) else '0';
    next_req           <= read_req and req_empty_n;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_id      <= (others => '0');
                start_addr  <= (others => '0');
                beat_len    <= (others => '0');
                start_to_4k <= (others => '0');
                end_from_4k <= (others => '0');
                sect_total  <= (others => '0');
            elsif clk_en = '1' then
                if next_req = '1' then
                    req_id      <= req_id_tmp;
                    start_addr  <= req_addr_tmp(ADDR_WIDTH-1 downto ADDR_ALIGN) & (ADDR_ALIGN-1 downto 0 => '0');
                    beat_len    <= RESIZE(SHIFT_RIGHT(req_len_tmp(11 downto 0) + req_addr_tmp(ADDR_ALIGN-1 downto 0), ADDR_ALIGN), 12-ADDR_ALIGN);
                    end_from_4k <= RESIZE(SHIFT_RIGHT(req_len_tmp(11 downto 0) + req_addr_tmp(11 downto 0)          , ADDR_ALIGN), 12-ADDR_ALIGN);
                    start_to_4k <= BOUNDARY_BEATS - req_addr_tmp(11 downto ADDR_ALIGN);
                    sect_total  <= RESIZE(SHIFT_RIGHT(req_len_tmp + req_addr_tmp(11 downto 0) , 12), 20);
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_handling <= false;
            elsif clk_en = '1' then
                if next_req = '1' then
                    req_handling <= true;
                elsif req_empty_n = '0' and last_sect_tmp and next_sect then
                    req_handling <= false;
                end if;
            end if;
        end if;
    end process;

    -- 4k boundary section
    last_sect_tmp  <= single_sect or last_sect;

    sect_total_tmp <= sect_total when first_sect else sect_total_buf;

    single_sect    <= (sect_total = 0);

    next_sect  <= req_handling and ready_for_sect;

    sect_addr  <= start_addr when first_sect else
                  sect_cnt & (11 downto 0 => '0');
    sect_len   <= beat_len     when     single_sect else
                  start_to_4k  when     first_sect and not last_sect else
                  end_from_4k  when not first_sect and     last_sect else
                  BOUNDARY_BEATS;
    
    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                first_sect <= false;
                last_sect <= false;
                sect_cnt <= (others => '0');
            elsif clk_en = '1' then
                if next_req = '1' then
                    first_sect <= true;
                    last_sect <= false;
                    sect_cnt <= req_addr_tmp(ADDR_WIDTH - 1 downto 12);
                elsif next_sect then
                    first_sect <= false;
                    last_sect <= (sect_total_tmp = 1);
                    sect_cnt <= sect_cnt + 1;
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                req_id_buf     <= (others=>'0');
                sect_addr_buf  <= (others => '0');
                sect_len_buf   <= (others => '0');
                last_sect_buf  <= false;
                sect_total_buf <= (others => '0');
            elsif clk_en = '1' then
                if next_sect then
                    req_id_buf     <= req_id;
                    sect_addr_buf  <= sect_addr;
                    sect_len_buf   <= sect_len;
                    last_sect_buf  <= last_sect_tmp;
                    sect_total_buf <= sect_total_tmp - 1;
                end if;
            end if;
        end if;
    end process; 

    must_one_burst : if (DATA_BYTES >= 4096/MAX_BURST_LENGTH) generate
    begin
        out_BURST_ID    <= req_id_buf;
        out_BURST_ADDR  <= sect_addr_buf;
        out_BURST_LEN   <= RESIZE(sect_len_buf, 8);
        out_BURST_VALID <= burst_valid;

        out_CTRL_ID     <= req_id;
        out_CTRL_INFO   <= "1" when last_sect_tmp else "0";
        out_CTRL_LEN    <= RESIZE(sect_len, 8);
        out_CTRL_VALID  <= '1' when next_sect else '0';

        ready_for_sect  <= not (burst_valid = '1' and in_BURST_READY = '0') and in_CTRL_READY(TO_INTEGER(req_id)) = '1';

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    burst_valid <= '0';
                elsif clk_en = '1' then
                    if next_sect then
                        burst_valid <= '1';
                    elsif in_BURST_READY = '1' then
                        burst_valid <= '0';
                    end if;
                end if;
            end if;
        end process;
    end generate must_one_burst;

    could_multi_bursts : if (DATA_BYTES < 4096/MAX_BURST_LENGTH) generate
        signal  addr_tmp        : UNSIGNED(ADDR_WIDTH - 1 downto 0);
        signal  addr_buf        : UNSIGNED(ADDR_WIDTH - 1 downto 0);
        signal  addr_step       : UNSIGNED(ADDR_ALIGN + 8 downto 0);
        signal  len_tmp         : UNSIGNED(7 downto 0);
        signal  len_buf         : UNSIGNED(7 downto 0);
        signal  id_buf          : UNSIGNED(ID_WIDTH-1 downto 0);
        signal  loop_cnt        : UNSIGNED(11 - NUM_BEAT_WIDTH - ADDR_ALIGN downto 0);
        signal  first_loop      : BOOLEAN;
        signal  last_loop       : BOOLEAN;
        signal  next_loop       : BOOLEAN;
        signal  ready_for_loop  : BOOLEAN;
        signal  sect_handling   : BOOLEAN;
    begin
        out_BURST_ID    <= id_buf;
        out_BURST_ADDR  <= addr_buf;
        out_BURST_LEN   <= len_buf;
        out_BURST_VALID <= burst_valid;

        out_CTRL_ID     <= req_id_buf;
        out_CTRL_INFO   <= "1" when last_sect_buf and last_loop else "0";
        out_CTRL_LEN    <= len_tmp;
        out_CTRL_VALID  <= '1' when next_loop else '0';

        next_loop       <= sect_handling and ready_for_loop;
        ready_for_loop  <= not (burst_valid = '1' and in_BURST_READY = '0') and in_CTRL_READY(TO_INTEGER(req_id_buf)) = '1';
        ready_for_sect  <= not sect_handling or (last_loop and next_loop);

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    burst_valid <= '0';
                elsif clk_en = '1' then
                    if next_loop then
                        burst_valid <= '1';
                    elsif in_BURST_READY = '1' then
                        burst_valid <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    sect_handling <= false;
                elsif clk_en = '1' then
                    if req_handling and not sect_handling then
                        sect_handling <= true;
                    elsif not req_handling and last_loop and next_loop then
                        sect_handling <= false;
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    first_loop <= false;
                    last_loop <= false;
                    loop_cnt <= (others => '0');
                elsif clk_en = '1' then
                    if next_sect then
                        first_loop <= true;
                        last_loop <= (sect_len(11 - ADDR_ALIGN downto NUM_BEAT_WIDTH) = 0);
                        loop_cnt <= sect_len(11 - ADDR_ALIGN downto NUM_BEAT_WIDTH);
                    elsif next_loop then
                        first_loop <= false;
                        last_loop <= (loop_cnt = 1);
                        loop_cnt <= loop_cnt - 1;
                    end if;
                end if;
            end if;
        end process;

        addr_tmp <= sect_addr_buf when first_loop else (addr_buf + addr_step);
        
        len_tmp  <= (others => '0') when (NUM_BEAT_WIDTH = 0) else
                    RESIZE(sect_len_buf(NUM_BEAT_WIDTH-1 downto 0), 8) when last_loop else
                    TO_UNSIGNED(2**NUM_BEAT_WIDTH-1, 8);

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if (reset = '1') then
                    addr_buf  <= (others => '0');
                    addr_step <= (others => '0');
                    len_buf   <= (others => '0');
                    id_buf    <= (others => '0');
                elsif clk_en = '1' then
                    if next_loop then
                        addr_buf  <= addr_tmp;
                        addr_step <= (RESIZE(len_tmp, 9) + 1) & (ADDR_ALIGN-1 downto 0 => '0');
                        len_buf   <= len_tmp;
                        id_buf    <= req_id_buf;
                    end if;
                end if;
            end if;
        end process;
    end generate could_multi_bursts;
end architecture behave;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_throttle is
    generic (
        CONSERVATIVE    : INTEGER := 0;
        ADDR_WIDTH      : INTEGER := 32;
        DATA_WIDTH      : INTEGER := 32;
        ID_WIDTH        : INTEGER := 1;
        NUM_OUTSTANDING : INTEGER := 16);
    port (
        clk             : in  STD_LOGIC;
        reset           : in  STD_LOGIC;
        clk_en          : in  STD_LOGIC;
        in_TOP_AWID     : in  UNSIGNED(ID_WIDTH-1 downto 0);
        in_TOP_AWADDR   : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        in_TOP_AWLEN    : in  UNSIGNED(7 downto 0);
        in_TOP_AWVALID  : in  STD_LOGIC;
        out_TOP_AWREADY : out STD_LOGIC;
        out_BUS_AWID    : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_BUS_AWADDR  : out UNSIGNED(ADDR_WIDTH-1 downto 0);
        out_BUS_AWLEN   : out UNSIGNED(7 downto 0);
        out_BUS_AWVALID : out STD_LOGIC;
        in_BUS_AWREADY  : in  STD_LOGIC;
        out_TOP_WID     : out UNSIGNED(ID_WIDTH-1 downto 0);
        in_TOP_WDATA    : in  UNSIGNED(DATA_WIDTH-1 downto 0);
        in_TOP_WSTRB    : in  UNSIGNED(DATA_WIDTH/8-1 downto 0);
        in_TOP_WVALID   : in  STD_LOGIC;
        out_TOP_WREADY  : out STD_LOGIC;
        out_BUS_WID     : out UNSIGNED(ID_WIDTH-1 downto 0);
        out_BUS_WDATA   : out UNSIGNED(DATA_WIDTH-1 downto 0);
        out_BUS_WSTRB   : out UNSIGNED(DATA_WIDTH/8-1 downto 0);
        out_BUS_WLAST   : out STD_LOGIC;
        out_BUS_WVALID  : out STD_LOGIC;
        in_BUS_WREADY   : in  STD_LOGIC);

    function log2 (x : INTEGER) return INTEGER is
        variable n, m : INTEGER;
    begin
        n := 0;
        m := 1;
        while m < x loop
            n := n + 1;
            m := m * 2;
        end loop;
        return n;
    end function log2;

    function gt_4 (x : INTEGER) return INTEGER is
        variable n : INTEGER;
    begin
        n := 4;
        if x > 4 then
            n := x;
        end if;
        return n;
    end function gt_4;

end entity vertex_map_gmem_m_axi_throttle;

architecture behav of vertex_map_gmem_m_axi_throttle is
    -- component
    component vertex_map_gmem_m_axi_reg_slice is
        generic (
            DATA_WIDTH  : integer := 8);
        port (
            clk         : in  std_logic;
            reset       : in  std_logic;
            s_data      : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            s_valid     : in  std_logic;
            s_ready     : out std_logic;
            m_data      : out UNSIGNED(DATA_WIDTH-1 downto 0);
            m_valid     : out std_logic;
            m_ready     : in  std_logic);
    end component vertex_map_gmem_m_axi_reg_slice;

    component vertex_map_gmem_m_axi_fifo is
        generic (
            MEM_STYLE         : STRING  := "shiftreg";
            DATA_WIDTH        : INTEGER := 8;
            ADDR_WIDTH        : INTEGER := 4;
            DEPTH             : INTEGER := 16);
        port (
            clk               : in  STD_LOGIC;
            reset             : in  STD_LOGIC;
            clk_en            : in  STD_LOGIC;
            if_full_n         : out STD_LOGIC;
            if_write          : in  STD_LOGIC;
            if_din            : in  UNSIGNED(DATA_WIDTH-1 downto 0);
            if_empty_n        : out STD_LOGIC;
            if_read           : in  STD_LOGIC;
            if_dout           : out UNSIGNED(DATA_WIDTH-1 downto 0);
            if_num_data_valid : out UNSIGNED(ADDR_WIDTH downto 0));
    end component vertex_map_gmem_m_axi_fifo;

    --local signal
    -- AW channel
    signal ost_burst_len      : UNSIGNED(7 downto 0);
    signal ost_burst_id       : UNSIGNED(ID_WIDTH-1 downto 0);
    signal ost_burst          : STD_LOGIC;

    signal next_burst         : STD_LOGIC;
    signal burst_len_cnt      : UNSIGNED(7 downto 0);

    -- W channel
    signal WID_Dummy          : UNSIGNED(ID_WIDTH-1 downto 0);
    signal WDATA_Dummy        : UNSIGNED(DATA_WIDTH - 1 downto 0);
    signal WSTRB_Dummy        : UNSIGNED(DATA_WIDTH/8 - 1 downto 0);
    signal WLAST_Dummy        : STD_LOGIC;
    signal WVALID_Dummy       : STD_LOGIC;

    signal ready_for_beat     : STD_LOGIC;
    signal next_beat          : STD_LOGIC;
    signal last_beat          : STD_LOGIC;

    signal throttling         : STD_LOGIC;
begin

    aggressive_gen : if (CONSERVATIVE = 0) generate
        signal burst_ready    : STD_LOGIC;
        signal write_burst    : STD_LOGIC;
        signal burst_pack     : UNSIGNED(ID_WIDTH+7 downto 0); 
        signal ost_burst_pack : UNSIGNED(ID_WIDTH+7 downto 0);
    begin
        
        fifo_burst : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => ID_WIDTH + 8,
            DEPTH             => NUM_OUTSTANDING,
            ADDR_WIDTH        => log2(NUM_OUTSTANDING))
        port map (
            clk               => clk,
            reset             => reset,
            clk_en            => clk_en,
            if_full_n         => burst_ready,
            if_write          => write_burst,
            if_din            => burst_pack,
            if_empty_n        => ost_burst,
            if_read           => next_burst,
            if_dout           => ost_burst_pack,
            if_num_data_valid => open);

        -- AW Channel
        out_BUS_AWID    <= in_TOP_AWID;
        out_BUS_AWADDR  <= in_TOP_AWADDR;
        out_BUS_AWLEN   <= in_TOP_AWLEN;
        out_BUS_AWVALID <= in_TOP_AWVALID AND burst_ready;
        out_TOP_AWREADY <= in_BUS_AWREADY AND burst_ready;

        write_burst     <= in_TOP_AWVALID AND in_BUS_AWREADY;
        burst_pack      <= in_TOP_AWID & in_TOP_AWLEN;
        ost_burst_id    <= ost_burst_pack(ID_WIDTH+7 downto 8);
        ost_burst_len   <= ost_burst_pack(7 downto 0);
        
        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    throttling <= '0';
                elsif clk_en = '1' then
                    throttling <= '1';
                end if;
            end if;
        end process;
    end generate;

    conservative_gen : if (CONSERVATIVE /= 0) generate
        signal burst_valid    : STD_LOGIC;
        signal read_burst     : STD_LOGIC;

        signal rs_in_ready    : STD_LOGIC;
        signal rs_in_valid    : STD_LOGIC;
        signal rs_out_ready   : STD_LOGIC;
        signal rs_out_valid   : STD_LOGIC;

        signal burst_pack     : UNSIGNED(ID_WIDTH + ADDR_WIDTH + 7 downto 0); 
        signal ost_burst_pack : UNSIGNED(ID_WIDTH + ADDR_WIDTH + 7 downto 0);
        signal rs_out_pack    : UNSIGNED(ID_WIDTH + ADDR_WIDTH + 7 downto 0);
    begin

        fifo_burst : vertex_map_gmem_m_axi_fifo
        generic map (
            DATA_WIDTH        => ID_WIDTH + ADDR_WIDTH + 8,
            DEPTH             => NUM_OUTSTANDING,
            ADDR_WIDTH        => log2(NUM_OUTSTANDING))
        port map (
            clk               => clk,
            reset             => reset,
            clk_en            => clk_en,
            if_full_n         => out_TOP_AWREADY,
            if_write          => in_TOP_AWVALID,
            if_din            => burst_pack,
            if_empty_n        => burst_valid,
            if_read           => read_burst,
            if_dout           => ost_burst_pack,
            if_num_data_valid => open);

        rs_burst : vertex_map_gmem_m_axi_reg_slice
        generic map (
            DATA_WIDTH      =>  ID_WIDTH + ADDR_WIDTH + 8)
        port map (
            clk             =>  clk,
            reset           =>  reset,
            s_data          =>  ost_burst_pack,
            s_valid         =>  rs_in_valid,
            s_ready         =>  rs_in_ready,
            m_data          =>  rs_out_pack,
            m_valid         =>  rs_out_valid,
            m_ready         =>  rs_out_ready);

        --AW Channel
        burst_pack          <= in_TOP_AWID & in_TOP_AWLEN & in_TOP_AWADDR;
        out_BUS_AWADDR      <= rs_out_pack(ADDR_WIDTH-1 downto 0);
        out_BUS_AWLEN       <= rs_out_pack(ADDR_WIDTH+7 downto ADDR_WIDTH);
        out_BUS_AWID        <= rs_out_pack(ID_WIDTH+ADDR_WIDTH+7 downto ADDR_WIDTH+8);
        out_BUS_AWVALID     <= '1' when rs_out_valid = '1' AND throttling = '0' else '0';
        rs_out_ready        <= '1' when in_BUS_AWREADY = '1' AND throttling = '0' else '0';

        rs_in_valid         <= '1' when burst_valid = '1' and ost_burst = '0' else '0';
        read_burst          <= '1' when rs_in_ready = '1' and ost_burst = '0' else '0';

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    ost_burst <= '0';
                elsif clk_en = '1' then
                    if (burst_valid and read_burst) = '1' and next_burst = '0' then
                        ost_burst <= '1';
                    elsif (burst_valid and read_burst) = '0' and next_burst = '1' then
                        ost_burst <= '0';
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    ost_burst_id  <= (others=>'0');
                    ost_burst_len <= (others=>'0');
                elsif clk_en = '1' then
                    if (burst_valid and read_burst) = '1'then
                        ost_burst_id  <= ost_burst_pack(ID_WIDTH+ADDR_WIDTH+7 downto ADDR_WIDTH+8);
                        ost_burst_len <= ost_burst_pack(ADDR_WIDTH+7 downto ADDR_WIDTH);
                    end if;
                end if;
            end if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    throttling <= '0';
                elsif clk_en = '1' then
                    if (rs_out_valid and rs_out_ready) = '1' and last_beat = '0' then
                        throttling <= '1';
                    elsif (rs_out_valid and rs_out_ready) = '0' and last_beat = '1' then
                        throttling <= '0';
                    end if;
                end if;
            end if;
        end process;
    end generate;

    -- W channel 
    out_BUS_WID    <= WID_Dummy;
    out_BUS_WDATA  <= WDATA_Dummy;
    out_BUS_WSTRB  <= WSTRB_Dummy;
    out_BUS_WLAST  <= WLAST_Dummy;
    out_BUS_WVALID <= WVALID_Dummy; 

    out_TOP_WID    <= ost_burst_id;
    out_TOP_WREADY <= ost_burst and ready_for_beat;

    ready_for_beat <= '1' when WVALID_Dummy = '0' or (in_BUS_WREADY and throttling) = '1' else '0';
    next_beat      <= ready_for_beat and ost_burst and in_TOP_WVALID;
    next_burst     <= '1' when (burst_len_cnt = ost_burst_len) and next_beat = '1' else '0';
    last_beat      <=  WLAST_Dummy and WVALID_Dummy and (in_BUS_WREADY and throttling);

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                WDATA_Dummy <= (others => '0');
                WSTRB_Dummy <= (others => '0');
                WID_Dummy   <= (others => '0');
            elsif clk_en = '1' then
                if next_beat = '1' then
                    WDATA_Dummy <= in_TOP_WDATA;
                    WSTRB_Dummy <= in_TOP_WSTRB;
                    WID_Dummy   <= ost_burst_id;
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                WVALID_Dummy <= '0';
            elsif clk_en = '1' then
                if next_beat = '1' then
                    WVALID_Dummy <= '1';
                elsif ready_for_beat = '1' then
                    WVALID_Dummy <= '0';
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                WLAST_Dummy <= '0';
            elsif clk_en = '1' then
                if next_burst = '1' then
                    WLAST_Dummy <= '1';
                elsif ready_for_beat = '1' then
                    WLAST_Dummy <= '0';
                end if;
            end if;
        end if;
    end process;

    process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                burst_len_cnt <= (others => '0');
            elsif clk_en = '1' then
                if next_burst = '1' then
                    burst_len_cnt <= (others => '0');
                elsif next_beat = '1' then
                    burst_len_cnt <= burst_len_cnt + 1;
                end if;
            end if;
        end if;
    end process;

end architecture behav;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_reg_slice is
    generic (
        DATA_WIDTH  : INTEGER := 8);
    port (
        -- system signals
        clk        : in  STD_LOGIC;
        reset       : in  STD_LOGIC;
        -- slave side
        s_data      : in  UNSIGNED(DATA_WIDTH-1 downto 0);
        s_valid     : in  STD_LOGIC;
        s_ready     : out STD_LOGIC;
        -- master side
        m_data      : out UNSIGNED(DATA_WIDTH-1 downto 0);
        m_valid     : out STD_LOGIC;
        m_ready     : in  STD_LOGIC);
end entity vertex_map_gmem_m_axi_reg_slice;

architecture behave of vertex_map_gmem_m_axi_reg_slice is
    constant ZERO                     : UNSIGNED(1 downto 0) := "10";
    constant ONE                      : UNSIGNED(1 downto 0) := "11";
    constant TWO                      : UNSIGNED(1 downto 0) := "01";
    signal   data_p1                  : UNSIGNED(DATA_WIDTH-1 downto 0);
    signal   data_p2                  : UNSIGNED(DATA_WIDTH-1 downto 0);
    signal   load_p1                  : STD_LOGIC;
    signal   load_p2                  : STD_LOGIC;
    signal   load_p1_from_p2          : STD_LOGIC;
    signal   s_ready_t                : STD_LOGIC;
    signal   state                    : UNSIGNED(1 downto 0);
    signal   next_st                  : UNSIGNED(1 downto 0);
begin
    s_ready <= s_ready_t;
    m_data  <= data_p1;
    m_valid <= state(0);

    load_p1 <= '1' when (state = ZERO and s_valid = '1') or
                        (state = ONE  and s_valid = '1' and m_ready = '1') or
                        (state = TWO  and m_ready = '1')
               else '0';

    load_p2         <= s_valid and s_ready_t;
    load_p1_from_p2 <= '1' when state = TWO else '0';

    data_p1_proc : process (clk)
    begin
        if (clk'event and clk = '1') then
            if (load_p1 = '1') then
                if (load_p1_from_p2 = '1') then
                    data_p1 <= data_p2;
                else
                    data_p1 <= s_data;
                end if;
            end if;
        end if;
    end process;

    data_p2_proc : process (clk)
    begin
        if (clk'event and clk = '1') then
            if (load_p2 = '1') then
                data_p2 <= s_data;
            end if;
        end if;
    end process;

    s_ready_t_proc : process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                s_ready_t <= '0';
            elsif (state = ZERO) then
                s_ready_t <= '1';
            elsif (state = ONE and next_st = TWO) then
                s_ready_t <= '0';
            elsif (state = TWO and next_st = ONE) then
                s_ready_t <= '1';
            end if;
        end if;
    end process;

    state_proc : process (clk)
    begin
        if (clk'event and clk = '1') then
            if (reset = '1') then
                state <= ZERO;
            else
                state <= next_st;
            end if;
        end if;
    end process;

    next_st_proc : process (state, s_valid, s_ready_t, m_ready)
    begin
        case state is
            when ZERO =>
                if (s_valid = '1' and s_ready_t = '1') then
                    next_st <= ONE;
                else
                    next_st <= ZERO;
                end if;
            when ONE =>
                if (s_valid = '0' and m_ready = '1') then
                    next_st <= ZERO;
                elsif (s_valid = '1' and m_ready = '0') then
                    next_st <= TWO;
                else
                    next_st <= ONE;
                end if;
            when TWO =>
                if (m_ready = '1') then
                    next_st <= ONE;
                else
                    next_st <= TWO;
                end if;
            when others =>
                next_st <= ZERO;
        end case;
    end process;

end architecture behave;


library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_fifo is
    generic (
        MEM_STYLE         : STRING  := "shiftreg";
        DATA_WIDTH        : INTEGER := 8;
        ADDR_WIDTH        : INTEGER := 4;
        DEPTH             : INTEGER := 16);
    port (
        clk               : in  STD_LOGIC;
        reset             : in  STD_LOGIC;
        clk_en            : in  STD_LOGIC;
        if_full_n         : out STD_LOGIC;
        if_write          : in  STD_LOGIC;
        if_din            : in  UNSIGNED(DATA_WIDTH-1 downto 0);
        if_empty_n        : out STD_LOGIC;
        if_read           : in  STD_LOGIC;
        if_dout           : out UNSIGNED(DATA_WIDTH-1 downto 0);
        if_num_data_valid : out UNSIGNED(ADDR_WIDTH downto 0));
end entity vertex_map_gmem_m_axi_fifo;

architecture behave of vertex_map_gmem_m_axi_fifo is

    signal push       : std_logic;
    signal pop        : std_logic;
    signal full_n     : std_logic := '1';
    signal empty_n    : std_logic := '0';
    signal dout_vld   : std_logic := '0';
    signal mOutPtr    : UNSIGNED(ADDR_WIDTH     downto 0) := (others => '0');
begin

    if_num_data_valid <= mOutPtr + 1 when dout_vld = '1' else (others=> '0');
    
    fifo_depth_1_gen: if (DEPTH = 1) generate
    begin
        if_full_n  <= not dout_vld;
        if_empty_n <= dout_vld;
        push       <= not dout_vld and if_write;
        pop        <= not dout_vld and if_write;
    end generate;
    
    fifo_depth_gt1_gen: if (DEPTH > 1) generate
    begin
        if_full_n  <= full_n;
        if_empty_n <= dout_vld;
        push       <= full_n and if_write;
        pop        <= empty_n and (not dout_vld or if_read);

        -- mOutPtr
        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    mOutPtr <= (others => '0');
                elsif (clk_en = '1') then
                    if push = '1' and pop = '0' then
                        mOutPtr <= mOutPtr + 1;
                    elsif push = '0' and pop = '1' then
                        mOutPtr <= mOutPtr - 1;
                    end if;
                end if;
            end if;
        end process;

        -- full_n
        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    full_n <= '1';
                elsif clk_en = '1' then
                    if push = '1' and pop = '0' then
                        if mOutPtr = DEPTH - 2 then
                            full_n <= '0';
                        else
                            full_n <= '1';
                        end if;
                    elsif push = '0' and pop = '1' then
                        full_n <= '1';
                    end if;
                end if;
            end if;
        end process;

        -- empty_n
        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    empty_n <= '0';
                elsif clk_en = '1' then
                    if push = '1' and pop = '0' then
                        empty_n <= '1';
                    elsif push = '0' and pop = '1' then
                        if mOutPtr = 1 then
                            empty_n <= '0';
                        else
                            empty_n <= '1';
                        end if;
                    end if;
                end if;
            end if;
        end process;
    end generate;

    -- dout_vld
    process (clk) begin
        if clk'event and clk = '1' then
            if reset = '1' then
                dout_vld <= '0';
            elsif clk_en = '1' then
                if pop = '1' then
                    dout_vld <= '1';
                elsif if_read = '1' then
                    dout_vld <= '0';
                end if;
            end if;
        end if;
    end process;

    -- shiftreg based fifo or depth == 1
    fifo_srl_gen: if ((MEM_STYLE = "shiftreg") or (DEPTH = 1)) generate
        component vertex_map_gmem_m_axi_srl is
            generic (
                DATA_WIDTH  : integer := 32;
                ADDR_WIDTH  : integer := 6;
                DEPTH       : integer := 64);
            port (
                clk         : in  std_logic;
                reset       : in  std_logic;
                clk_en      : in  std_logic;
                we          : in  std_logic;
                din         : in  UNSIGNED(DATA_WIDTH-1 downto 0);
                raddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
                re          : in  std_logic;
                dout        : out UNSIGNED(DATA_WIDTH-1 downto 0));
        end component;
        signal raddr      : UNSIGNED(ADDR_WIDTH - 1 downto 0) := (others => '0');
    begin
        U_ffo_srl: vertex_map_gmem_m_axi_srl
        generic map (
            DATA_WIDTH  => DATA_WIDTH,
            ADDR_WIDTH  => ADDR_WIDTH,
            DEPTH       => DEPTH)
        port map (
            clk         => clk,
            reset       => reset,
            clk_en      => clk_en,
            we          => push,
            din         => if_din,
            re          => pop,
            raddr       => raddr,
            dout        => if_dout);

        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    raddr <= (others => '0');
                elsif (clk_en = '1') then
                    if (push = '1' and pop = '0' and empty_n = '1') then
                        raddr <= raddr + 1;
                    elsif (push = '0' and pop = '1' and raddr /= 0) then
                        raddr <= raddr - 1;
                    end if;
                end if;
            end if;
        end process;
    end generate;

    -- mem based fifo (depth must be greater than 1)
    fifo_mem_gen: if ((MEM_STYLE /= "shiftreg") and (DEPTH > 1)) generate
        component vertex_map_gmem_m_axi_mem is
            generic (
                MEM_STYLE   : string  := "auto";
                DATA_WIDTH  : integer := 32;
                ADDR_WIDTH  : integer := 6;
                DEPTH       : integer := 64);
            port (
                clk         : in  std_logic;
                reset       : in  std_logic;
                clk_en      : in  std_logic;
                we          : in  std_logic;
                waddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
                din         : in  UNSIGNED(DATA_WIDTH-1 downto 0);
                re          : in  std_logic;
                raddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
                dout        : out UNSIGNED(DATA_WIDTH-1 downto 0));
        end component;

        signal waddr      : UNSIGNED(ADDR_WIDTH - 1 downto 0) := (others => '0');
        signal raddr      : UNSIGNED(ADDR_WIDTH - 1 downto 0) := (others => '0');
        signal wnext      : UNSIGNED(ADDR_WIDTH - 1 downto 0);
        signal rnext      : UNSIGNED(ADDR_WIDTH - 1 downto 0);
    begin
        U_ffo_mem: vertex_map_gmem_m_axi_mem
        generic map (
            MEM_STYLE   => MEM_STYLE,
            DATA_WIDTH  => DATA_WIDTH,
            ADDR_WIDTH  => ADDR_WIDTH,
            DEPTH       => DEPTH)
        port map (
            clk         => clk,
            reset       => reset,
            clk_en      => clk_en,
            we          => push,
            waddr       => waddr,
            din         => if_din,
            re          => pop,
            raddr       => rnext,
            dout        => if_dout);

        wnext <= waddr           when push = '0'        else
                 (others => '0') when waddr = DEPTH - 2 else
                 waddr + 1;
        rnext <= raddr           when pop = '0'         else
                 (others => '0') when raddr = DEPTH - 2 else
                 raddr + 1;

        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    waddr <= (others => '0');
                elsif (clk_en = '1') then
                    waddr <= wnext;
                end if;
            end if;
        end process;

        process (clk) begin
            if clk'event and clk = '1' then
                if reset = '1' then
                    raddr <= (others => '0');
                elsif (clk_en = '1') then
                    raddr <= rnext;
                end if;
            end if;
        end process;
    end generate;

end architecture behave;   

library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_srl is
    generic (
        DATA_WIDTH  : integer := 32;
        ADDR_WIDTH  : integer := 6;
        DEPTH       : integer := 64);
    port (
        clk         : in  std_logic;
        reset       : in  std_logic;
        clk_en      : in  std_logic;
        we          : in  std_logic;
        din         : in  UNSIGNED(DATA_WIDTH-1 downto 0);
        raddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        re          : in  std_logic;
        dout        : out UNSIGNED(DATA_WIDTH-1 downto 0));
end vertex_map_gmem_m_axi_srl;

architecture behav of vertex_map_gmem_m_axi_srl is
begin

    fifo_depth_1_gen: if (DEPTH = 1) generate
    begin
        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    dout <= (others => '0');
                elsif clk_en = '1' and we = '1' then
                    dout <= din;
                end if;
            end if;
        end process;
    end generate;

    fifo_depth_gt1_gen: if (DEPTH > 1) generate
        type SRL_ARRAY is array (0 to DEPTH-2) of UNSIGNED(DATA_WIDTH-1 downto 0);
        signal mem : SRL_ARRAY;
    begin
        process (clk)
        begin
            if (clk'event and clk = '1') then
                if clk_en = '1' and we = '1' then
                    for i in 0 to DEPTH - 3 loop
                        mem(i+1) <= mem(i);
                    end loop;
                    mem(0) <= din;
                end if;
            end  if;
        end process;

        process (clk)
        begin
            if (clk'event and clk = '1') then
                if reset = '1' then
                    dout <= (others => '0');
                elsif clk_en = '1' and re = '1' then
                    dout <= mem(to_integer(raddr));
                end if;
            end if;
        end process;
    end generate;

end architecture behav;

library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;

entity vertex_map_gmem_m_axi_mem is
    generic (
        MEM_STYLE   : string  := "auto";
        DATA_WIDTH  : integer := 32;
        ADDR_WIDTH  : integer := 6;
        DEPTH       : integer := 64);
    port (
        clk         : in  std_logic;
        reset       : in  std_logic;
        clk_en      : in  std_logic;
        we          : in  std_logic;
        waddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        din         : in  UNSIGNED(DATA_WIDTH-1 downto 0);
        re          : in  std_logic;
        raddr       : in  UNSIGNED(ADDR_WIDTH-1 downto 0);
        dout        : out UNSIGNED(DATA_WIDTH-1 downto 0));
end vertex_map_gmem_m_axi_mem;

architecture behav of vertex_map_gmem_m_axi_mem is

    signal raddr_reg : UNSIGNED(ADDR_WIDTH - 1 downto 0) := (others => '0');
    -- depth must be larger than 1
    type MEM_ARRAY is array (0 to DEPTH - 2) of UNSIGNED(DATA_WIDTH - 1 downto 0);
    signal mem : MEM_ARRAY;
    -- read write collision attribute settings.
    attribute ram_style: string;
    attribute ram_style of mem: signal is MEM_STYLE;
    attribute rw_addr_collision : string;
    attribute rw_addr_collision of mem : signal is "yes";

begin

    process (clk) begin
        if clk'event and clk = '1' then
            if clk_en = '1' then
                raddr_reg <= raddr;
            end if;
        end if;
    end process;

    process (clk) begin
        if clk'event and clk = '1' then
            if reset = '1' then
                dout <= ( others=> '0');
            elsif (clk_en = '1' and re = '1') then
                dout <= mem(to_integer(raddr_reg));
            end if;
        end if;
    end process;

    process (clk) begin
        if clk'event and clk = '1' then
            if clk_en = '1' and we = '1' then
                mem(to_integer(waddr)) <= din;
            end if;
        end if;
    end process;
end architecture behav;
